// Enhanced application with improved error handling, input validation, and security
const express = require('express');
const app = express();

// Security middleware - in production, consider using helmet.js
// For now, we'll implement basic security headers manually
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Remove powered by header
  res.removeHeader('X-Powered-By');

  next();
});

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request timeout middleware
app.use((req, res, next) => {
  req.setTimeout(10000, () => {
    res.status(408).json({
      error: 'Request Timeout',
      message: 'The request took too long to process'
    });
  });
  next();
});

// Basic request logging
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} - ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any were expected
    if (Object.keys(req.query).length > 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Health endpoint does not accept query parameters'
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to process health check'
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit, offset, search } = req.query;

    // Validate limit parameter
    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Limit must be a number between 1 and 100'
        });
      }
    }

    // Validate offset parameter
    if (offset !== undefined) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Offset must be a non-negative number'
        });
      }
    }

    // Validate search parameter (basic sanitization example)
    if (search !== undefined) {
      if (typeof search !== 'string' || search.length > 50) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Search must be a string with maximum length of 50 characters'
        });
      }

      // Basic SQL injection prevention (though we're not using a DB here)
      const sqlInjectionPattern = /(union|select|insert|update|delete|drop|--)/i;
      if (sqlInjectionPattern.test(search)) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Invalid search parameter'
        });
      }
    }

    // Mock data - in a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply pagination if specified
    let filteredUsers = users;

    // Apply search filter if specified
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const offsetNum = parseInt(offset) || 0;
    const limitNum = parseInt(limit) || filteredUsers.length;
    const paginatedUsers = filteredUsers.slice(offsetNum, offsetNum + limitNum);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        offset: offsetNum,
        limit: limitNum,
        hasMore: offsetNum + limitNum < filteredUsers.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // Don't expose internal error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message || 'Internal Server Error';

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : 'Bad Request',
    message: message
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to exit gracefully
  // process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

