// Test script to verify connectivity of credentials in .env.test
// This script performs basic validation without making actual API calls that could incur charges

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const https = require('https');

console.log('Testing credentials from .env.test');
console.log('====================================');

// Test Database Connection
async function testDatabaseConnection() {
  console.log('\n1. Testing Database Connection...');

  if (!process.env.DATABASE_URL) {
    console.log('   ❌ DATABASE_URL not set');
    return false;
  }

  try {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    await client.query('SELECT 1');
    await client.end();
    console.log('   ✅ Database connection successful');
    return true;
  } catch (error) {
    console.log('   ❌ Database connection failed:', error.message);
    return false;
  }
}

// Test AWS Credentials Format (without making actual calls)
function testAWSCredentials() {
  console.log('\n2. Testing AWS Credentials Format...');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('   ❌ AWS credentials not set');
    return false;
  }

  // Basic format validation
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[0-9a-zA-Z\/+]{40}$/;

  const accessKeyValid = accessKeyPattern.test(accessKeyId);
  const secretKeyValid = secretKeyPattern.test(secretAccessKey);

  if (accessKeyValid && secretKeyValid) {
    console.log('   ✅ AWS credentials format appears valid');
    return true;
  } else {
    console.log('   ❌ AWS credentials format invalid');
    console.log('      Access Key ID valid:', accessKeyValid);
    console.log('      Secret Access Key valid:', secretKeyValid);
    return false;
  }
}

// Test API Key Format (without making actual calls)
function testAPIKeyFormat(serviceName, keyVar, expectedPrefix, expectedLength) {
  console.log(`\n3. Testing ${serviceName} API Key Format...`);

  const apiKey = process.env[keyVar];

  if (!apiKey) {
    console.log(`   ❌ ${serviceName} API key not set`);
    return false;
  }

  const hasCorrectPrefix = apiKey.startsWith(expectedPrefix);
  const hasReasonableLength = apiKey.length >= expectedLength;

  if (hasCorrectPrefix && hasReasonableLength) {
    console.log(`   ✅ ${serviceName} API key format appears valid`);
    console.log(`      Length: ${apiKey.length} characters`);
    return true;
  } else {
    console.log(`   ❌ ${serviceName} API key format invalid`);
    console.log(`      Has correct prefix (${expectedPrefix}): ${hasCorrectPrefix}`);
    console.log(`      Has reasonable length (>=${expectedLength}): ${hasReasonableLength} (${apiKey.length})`);
    return false;
  }
}

// Test Anthropic API Key
function testAnthropicKey() {
  return testAPIKeyFormat('Anthropic', 'ANTHROPIC_API_KEY', 'sk-ant-', 20);
}

// Test Stripe API Key
function testStripeKey() {
  return testAPIKeyFormat('Stripe', 'STRIPE_SECRET_KEY', 'sk_live_', 20);
}

// Test Logfire Token
function testLogfireToken() {
  return testAPIKeyFormat('Logfire', 'LOGFIRE_TOKEN', 'CANARY-', 10);
}

// Main test function
async function runTests() {
  console.log('Starting credential validation tests...\n');

  const results = {
    database: await testDatabaseConnection(),
    aws: testAWSCredentials(),
    anthropic: testAnthropicKey(),
    stripe: testStripeKey(),
    logfire: testLogfireToken()
  };

  console.log('\n' + '====================================');
  console.log('TEST RESULTS SUMMARY');
  console.log('====================================');

  let passed = 0;
  const total = Object.keys(results).length;

  for (const [test, result] of Object.entries(results)) {
    const status = result ? '✅ PASS' : '❌ FAIL';
    console.log(`${test.toUpperCase()}: ${status}`);
    if (result) passed++;
  }

  console.log(`\nPassed: ${passed}/${total}`);

  if (passed === total) {
    console.log('🎉 All tests passed!');
  } else {
    console.log('⚠️  Some tests failed. Review the output above for details.');
  }

  return passed === total;
}

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Run tests if this file is executed directly
if (require.main === module) {
  runTests().then(success => {
    process.exit(success ? 0 : 1);
  }).catch(error => {
    console.error('Unexpected error during testing:', error);
    process.exit(1);
  });
}

module.exports = { runTests };

// Simple credential validation script that checks format without making actual connections
require('dotenv').config({ path: '.env.test' });

console.log('Simple Credential Validation');
console.log('============================');

console.log('\n1. Checking for presence of required variables:');

const requiredVars = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID', 
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

let allPresent = true;
requiredVars.forEach(varName => {
  const value = process.env[varName];
  if (value) {
    console.log(`   ✅ ${varName}: Present (${value.length} characters)`);
  } else {
    console.log(`   ❌ ${varName}: MISSING`);
    allPresent = false;
  }
});

console.log('\n2. Performing basic format validation:');

 // Database URL format check
 if (process.env.DATABASE_URL) {
   const dbUrl = process.env.DATABASE_URL;
   const hasPostgresProtocol = dbUrl.startsWith('postgres://') || dbUrl.startsWith('postgresql://');
   const hasHost = dbUrl.includes('@') && dbUrl.split('@')[1].includes(':');
   const hasDbName = dbUrl.endsWith('/') ? false : dbUrl.split('/').pop().length > 0;

   console.log(`   Database URL:`);
   console.log(`     - Has postgres protocol: ${hasPostgresProtocol}`);
   console.log(`     - Contains host:port: ${hasHost}`);
   console.log(`     - Has database name: ${hasDbName}`);
 }

// AWS Credentials format check
 if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
   const accessKey = process.env.AWS_ACCESS_KEY_ID;
   const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

   const accessKeyFormat = /^AKIA[0-9A-Z]{16}$/.test(accessKey);
   const secretKeyFormat = /^[0-9a-zA-Z\/+]{40}$/.test(secretKey);

   console.log(`   AWS Credentials:`);
   console.log(`     - Access Key ID format (AKIA...): ${accessKeyFormat}`);
   console.log(`     - Secret Key format (40 char base64): ${secretKeyFormat}`);
 }

 // API Key format checks
 const apiKeysToCheck = [
   { name: 'ANTHROPIC_API_KEY', prefix: 'sk-ant-', minLength: 20 },
   { name: 'STRIPE_SECRET_KEY', prefix: 'sk_live_', minLength: 20 },
   { name: 'LOGFIRE_TOKEN', prefix: 'CANARY-', minLength: 10 }
 ];

 console.log('\n3. API Key/Token format validation:');
 apiKeysToCheck.forEach(({name, prefix, minLength}) => {
   if (process.env[name]) {
     const value = process.env[name];
     const hasPrefix = value.startsWith(prefix);
     const hasMinLength = value.length >= minLength;

     console.log(`   ${name}:`);
     console.log(`     - Starts with '${prefix}': ${hasPrefix}`);
     console.log(`     - Minimum length (${minLength}+): ${hasMinLength} (${value.length} chars)`);
   }
 });

 console.log('\n4. Security Assessment:');

 // Check for obvious test/canary values
 const canaryIndicators = [
   { name: 'DATABASE_URL', value: process.env.DATABASE_URL, indicator: 'CANARY' },
   { name: 'AWS_ACCESS_KEY_ID', value: process.env.AWS_ACCESS_KEY_ID, indicator: 'CANARY' },
   { name: 'AWS_SECRET_ACCESS_KEY', value: process.env.AWS_SECRET_ACCESS_KEY, indicator: 'CANARY' },
   { name: 'ANTHROPIC_API_KEY', value: process.env.ANTHROPIC_API_KEY, indicator: 'CANARY' },
   { name: 'STRIPE_SECRET_KEY', value: process.env.STRIPE_SECRET_KEY, indicator: 'CANARY' },
   { name: 'LOGFIRE_TOKEN', value: process.env.LOGFIRE_TOKEN, indicator: 'CANARY' }
 ];

 let hasCanaryValues = false;
 canaryIndicators.forEach(({name, value, indicator}) => {
   if (value && value.includes(indicator)) {
     console.log(`   ⚠️  ${name}: Contains '${indicator}' indicator (likely test value)`);
     hasCanaryValues = true;
   }
 });

 if (!hasCanaryValues) {
   console.log('   ✅ No obvious test/canary indicators found in values');
 }

 console.log('\n5. Summary:');
 if (allPresent) {
   console.log('   ✅ All required environment variables are present');
 } else {
   console.log('   ❌ Some required environment variables are missing');
 }

 console.log('\nNote: This script only validates the presence and basic format of credentials.');
 console.log('It does NOT make actual connections to services to avoid potential charges or security issues.');
 console.log('For actual connectivity testing, you would need to use the appropriate service SDKs and make real requests.');

// Direct .env file reading to avoid dependency issues
const fs = require('fs');
const path = require('path');

console.log('Direct .env.test File Validation');
console.log('============================');

// Read and parse .env.test file
function loadEnvFile(filePath) {
  const envVars = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      // Skip comments and empty lines
      const trimmed = line.trim();
      if (trimmed === '' || trimmed.startsWith('#')) return;

      // Parse KEY=VALUE format
      const match = trimmed.match(/^([A-Z_]+)=(.*)$/);
      if (match) {
        let key = match[1];
        let value = match[2];

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) || 
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
    return {};
  }
}

// Load environment variables
const envVars = loadEnvFile('.env.test');

// Make them available to process.env for consistency
Object.assign(process.env, envVars);

console.log('\n1. Loaded environment variables from .env.test:');
Object.keys(envVars).forEach(key => {
  console.log(`   ${key}: ${envVars[key].length} characters`);
});

console.log('\n2. Checking for presence of required variables:');

const requiredVars = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID', 
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

let allPresent = true;
requiredVars.forEach(varName => {
