// Improved application with enhanced error handling, input validation, and security practices

const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate request (though minimal for health check)
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Input validation
    let validatedLimit = parseInt(limit) || 10;
    let validatedOffset = parseInt(offset) || 0;

    // Sanity checks
    if (isNaN(validatedLimit) || validatedLimit < 1 || validatedLimit > 100) {
      validatedLimit = 10;
    }

    if (isNaN(validatedOffset) || validatedOffset < 0) {
      validatedOffset = 0;
    }

    // Mock user data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search && typeof search === 'string') {
      // Sanitize search input (basic example)
      const sanitizedSearch = search.trim().toLowerCase();
      if (sanitizedSearch) {
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(sanitizedSearch) || 
          user.email.toLowerCase().includes(sanitizedSearch)
        );
      }
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(
      validatedOffset, 
      validatedOffset + validatedLimit
    );

    res.json({
      count: filteredUsers.length,
      limit: validatedLimit,
      offset: validatedOffset,
      users: paginatedUsers
    });
  } catch (error) {
    // Log the error for debugging (in production, use proper logging)
    console.error('Error in /users endpoint:', error);

    // Return generic error message to client
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Route not found' 
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Determine status code
  const statusCode = error.status || 500;

  // Prepare error response
  const errorResponse = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message || 'Unknown error'
  };

  // Add additional error details in development
  if (process.env.NODE_ENV !== 'production' && error.expose) {
    errorResponse.details = error.details;
  }

  res.status(statusCode).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

