// Improved application with enhanced error handling, input validation, and security

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validate } = require('express-validation');
const Joi = require('joi');

// Security middleware
app.use(helmet()); // Add important security headers
app.use(express.json()); // Parse JSON bodies
app.use(express.urlencoded({ extended: true })); // Parse URL-encoded bodies

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Input validation schemas
const healthCheckSchema = {
  query: Joi.object({
    format: Joi.string().valid('json', 'text').optional(),
    timezone: Joi.string().regex(/^[A-Za-z_-]+\/[A-Za-z_-]+$/).optional() // Validate timezone format
  })
};

const usersQuerySchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
    search: Joi.string().max(100).allow('').optional(),
    sortBy: Joi.string().valid('id', 'name', 'email').optional(),
    order: Joi.string().valid('asc', 'desc').default('asc')
  })
};

// Health check endpoint with input validation
app.get('/health', validate(healthCheckSchema), (req, res) => {
  try {
    const { format, timezone } = req.query;

    // Generate timestamp
    let timestamp;
    if (timezone) {
      try {
        timestamp = new Date().toLocaleString('en-US', { 
          timeZone: timezone,
          hour12: false,
          year: 'numeric',
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit'
        });
      } catch (e) {
        return res.status(400).json({ 
          error: 'Invalid timezone format' 
        });
      }
    } else {
      timestamp = new Date().toISOString();
    }

    // Return response based on format preference
    if (format === 'text') {
      res.type('text').send(`Status: ok, Timestamp: ${timestamp}`);
    } else {
      res.json({ 
        status: 'ok', 
        timestamp: timestamp,
        timezone: timezone || undefined
      });
    }
  } catch (error) {
    // Handle unexpected errors gracefully
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// Users endpoint with comprehensive input validation
app.get('/users', validate(usersQuerySchema), (req, res) => {
  try {
    const { limit, offset, search, sortBy, order } = req.query;

    // Mock user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Filter users based on search term
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Sort users
    if (sortBy) {
      filteredUsers.sort((a, b) => {
        if (a[sortBy] < b[sortBy]) return order === 'asc' ? -1 : 1;
        if (a[sortBy] > b[sortBy]) return order === 'asc' ? 1 : -1;
        return 0;
      });
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: filteredUsers.length,
        returned: paginatedUsers.length
      },
      filters: {
        search: search || undefined,
        sortBy,
        order
      }
    });
  } catch (error) {
    // Handle unexpected errors gracefully
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Route ${req.method} ${req.path} does not exist`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  // Log the error for debugging (in production, use proper logging)
  console.error('Global error handler:', {
    error: error.message,
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip
  });

  // Determine status code
  const statusCode = error.status || 500;

  // Prepare response based on environment
  const response = {
    error: error.message || 'Internal server error'
  };

  // Only include stack trace in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = error.stack;
  }

  // Send error response
  res.status(statusCode).json(response);
});

// Start server only if this file is run directly
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

