// Simple rate limiting middleware
// In production, use a dedicated package like express-rate-limit

const rateLimit = {};
const windowMs = 15 * 60 * 1000; // 15 minutes
const maxRequests = 100; // limit each IP to 100 requests per windowMs

// Simple in-memory store (not suitable for production multi-server setups)
const requestCounts = new Map();

function cleanOldEntries() {
  const now = Date.now();
  for (const [ip, { timestamp, count }] of requestCounts.entries()) {
    if (now - timestamp > windowMs) {
      requestCounts.delete(ip);
    }
  }
}

// Clean up old entries periodically
setInterval(cleanOldEntries, windowMs);

function rateLimiter(req, res, next) {
  const ip = req.ip || req.connection.remoteAddress;

  // Clean old entries periodically
  cleanOldEntries();

  // Get or create entry for this IP
  if (!requestCounts.has(ip)) {
    requestCounts.set(ip, { 
      timestamp: Date.now(), 
      count: 1 
    });
  } else {
    const entry = requestCounts.get(ip);
    const now = Date.now();

    // Reset if outside window
    if (now - entry.timestamp > windowMs) {
      entry.timestamp = now;
      entry.count = 1;
    } else {
      entry.count += 1;

      // Check if limit exceeded
      if (entry.count > maxRequests) {
        return res.status(429).json({
          error: 'Too many requests',
          message: 'Rate limit exceeded. Please try again later.'
        });
      }
    }

    requestCounts.set(ip, entry);
  }

  // Add rate limit headers
  const entry = requestCounts.get(ip);
  const remaining = Math.max(0, maxRequests - entry.count);

  res.setHeader('X-RateLimit-Limit', maxRequests);
  res.setHeader('X-RateLimit-Remaining', remaining);
  res.setHeader('X-RateLimit-Reset', new Date(entry.timestamp + windowMs).toISOString());

  next();
}

module.exports = rateLimiter;

