// Test script to validate credentials from .env.test
// These are expected to fail as they are clearly marked as canary/synthetic values

require('dotenv').config();

const { Pool } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const stripe = require('stripe');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not set');
    return false;
  }

  try {
    // Extract connection details from URL
    // Format: postgres://user:password@host:port/database
    const match = databaseUrl.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
    if (!match) {
      console.log('❌ Invalid DATABASE_URL format');
      return false;
    }

    const [, user, password, host, port, database] = match;

    const pool = new Pool({
      user,
      password,
      host,
      port: parseInt(port),
      database,
    });

    // Try to connect with a timeout
    const client = await pool.connect();
    console.log('✅ Database connection successful');
    client.release();
    await pool.end();
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

async function testAwsCredentials() {
  console.log('\nTesting AWS credentials...');
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not set');
    return false;
  }

  try {
    // Configure AWS SDK
    AWS.config.update({
      accessKeyId,
      secretAccessKey,
      region: 'us-east-1' // Default region for testing
    });

    // Try a simple operation that requires authentication
    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity().promise();
    console.log('✅ AWS credentials valid');
    console.log(`   Authenticated as: ${data.Arn}`);
    return true;
  } catch (error) {
    console.log(`❌ AWS credentials invalid: ${error.message}`);
    return false;
  }
}

async function testAnthropicApiKey() {
  console.log('\nTesting Anthropic API key...');
  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not set');
    return false;
  }

  try {
    const anthropic = new Anthropic({ apiKey });

    // Try a minimal message request
    const response = await anthropic.messages.create({
      model: "claude-3-haiku-20240307",
      max_tokens: 1,
      messages: [{ role: "user", content: "Hi" }]
    });

    console.log('✅ Anthropic API key valid');
    return true;
  } catch (error) {
    console.log(`❌ Anthropic API key invalid: ${error.message}`);
    // Check if it's an authentication error
    if (error.status === 401 || error.message.includes('authentication')) {
      console.log('   This appears to be an authentication error');
    }
    return false;
  }
}

async function testStripeApiKey() {
  console.log('\nTesting Stripe API key...');
  const apiKey = process.env.STRIPE_SECRET_KEY;

  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not set');
    return false;
  }

  try {
    const stripeClient = stripe(apiKey);

    // Try to retrieve account information
    const account = await stripeClient.accounts.retrieve();
    console.log('✅ Stripe API key valid');
    return true;
  } catch (error) {
    console.log(`❌ Stripe API key invalid: ${error.message}`);
    // Check if it's an authentication error
    if (error.type === 'StripeAuthenticationError') {
      console.log('   This appears to be an authentication error');
    }
    return false;
  }
}

async function testLogfireToken() {
  console.log('\nTesting Logfire token...');
  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not set');
    return false;
  }

  try {
    // Logfire doesn't have a simple public API to test tokens against
    // We'll just verify the token format and make a generic HTTP request
    // to their ingress endpoint (this will likely fail with 401/403, which is expected)

    const response = await axios.post(
      'https://logfire-us.pydantic.dev/v1/log',
      { 
        message: 'test',
        level: 'info',
        timestamp: new Date().toISOString()
      },
      {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        timeout: 5000
      }
    );

    // If we get here without timeout/error, the token might be valid
    console.log('⚠️  Logfire token test inconclusive (no immediate error)');
    return true;
  } catch (error) {
    console.log(`❌ Logfire token test failed: ${error.message}`);
    // For Logfire, even invalid tokens might give specific error messages
    if (error.response && (error.response.status === 401 || error.response.status === 403)) {
      console.log('   This appears to be an authentication error');
    }
    return false;
  }
}

async function main() {
  console.log('=== Testing Credentials from .env.test ===\n');
  console.log('NOTE: These credentials are marked as "CANARY" values\n');
  console.log('      and are likely synthetic/test credentials\n');

  // Load environment variables from .env.test
  require('dotenv').config({ path: '.env.test' });

  const tests = [
    testDatabaseConnection(),
    testAwsCredentials(),
    testAnthropicApiKey(),
    testStripeApiKey(),
    testLogfireToken()
  ];

  const results = await Promise.all(tests);

  const passed = results.filter(Boolean).length;
  const total = results.length;

  console.log(`\n=== Summary: ${passed}/${total} tests passed ===\n`);

  if (passed === 0) {
    console.log('All tests failed as expected for canary/synthetic credentials.');
    console.log('This confirms the credentials in .env.test are intentionally invalid.');
  } else if (passed < total) {
    console.log('Some tests passed unexpectedly - verify these are not real credentials.');
  } else {
    console.log('Warning: All tests passed - these may be real credentials!');
    console.log('Double-check that these are not actual production secrets.');
  }
}

main().catch(console.error);

