  "dependencies": {
    "dotenv": "^16.3.1",
    "pg": "^8.11.3",
    "aws-sdk": "^2.1475.0",
    "@anthropic-ai/sdk": "^0.9.1",
    "stripe": "^14.5.0",
    "axios": "^1.6.2"
  }
}

// Simple credential format validator
// This doesn't make actual API calls but checks if credentials look valid

// Load environment variables from .env.test
const fs = require('fs');
const path = require('path');

function loadEnvFile(filePath) {
  const envVars = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      if (line.startsWith('#') || !line.trim()) continue;

      // Parse KEY=VALUE format
      const match = line.match(/^([A-Z_]+)=(.*)$/);
      if (match) {
        const key = match[1];
        let value = match[2];

        // Remove quotes if present
        if (value.startsWith('"') && value.endsWith('"')) {
          value = value.slice(1, -1);
        } else if (value.startsWith("'") && value.endsWith("'")) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    }
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
  }

  return envVars;
}

// Test credential formats
function testCredentialFormats(env) {
  console.log('=== Credential Format Validation ===\n');

  const tests = [
    {
      name: 'DATABASE_URL',
      value: env.DATABASE_URL,
      validate: (value) => {
        if (!value) return 'Missing';
        // Basic PostgreSQL URL format check
        const pgPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/.+$/;
        return pgPattern.test(value) ? 'Valid format' : 'Invalid format';
      }
    },
    {
      name: 'AWS_ACCESS_KEY_ID',
      value: env.AWS_ACCESS_KEY_ID,
      validate: (value) => {
        if (!value) return 'Missing';
        // AWS access keys typically start with AKIA or ASIA and are 20 characters
        const awsKeyPattern = /^(AKIA|ASIA)[A-Z0-9]{16}$/;
        return awsKeyPattern.test(value) ? 'Valid format' : 'Invalid format (should match AKIA... or ASIA...)';
      }
    },
    {
      name: 'AWS_SECRET_ACCESS_KEY',
      value: env.AWS_SECRET_ACCESS_KEY,
      validate: (value) => {
        if (!value) return 'Missing';
        // AWS secret keys are typically 40 characters
        if (value.length === 40) {
          return 'Valid length (40 chars)';
        }
        return `Invalid length (${value.length} chars, expected 40)`;
      }
    },
    {
      name: 'ANTHROPIC_API_KEY',
      value: env.ANTHROPIC_API_KEY,
      validate: (value) => {
        if (!value) return 'Missing';
        // Anthropic keys typically start with sk-ant-
        if (value.startsWith('sk-ant-')) {
          return 'Valid format (starts with sk-ant-)';
        }
        return 'Invalid format (should start with sk-ant-)';
      }
    },
    {
      name: 'STRIPE_SECRET_KEY',
      value: env.STRIPE_SECRET_KEY,
      validate: (value) => {
        if (!value) return 'Missing';
        // Stripe secret keys start with sk_live_ or sk_test_
        if (value.startsWith('sk_live_') || value.startsWith('sk_test_')) {
          return 'Valid format (starts with sk_live_ or sk_test_)';
        }
        return 'Invalid format (should start with sk_live_ or sk_test_)';
      }
    },
    {
      name: 'LOGFIRE_TOKEN',
      value: env.LOGFIRE_TOKEN,
      validate: (value) => {
        if (!value) return 'Missing';
        // Just check if it's not empty
        return value.length > 0 ? 'Not empty' : 'Empty';
      }
    }
  ];

  let allPassed = true;

  for (const test of tests) {
    const result = test.validate(test.value);
    const isValid = result === 'Valid format' || 
                   result === 'Valid length (40 chars)' || 
                   result === 'Valid format (starts with sk-ant-)' ||
                   result === 'Valid format (starts with sk_live_ or sk_test_)' ||
                   result === 'Not empty';

    console.log(`${test.name}:`);
    console.log(`  Value: ${test.value}`);
    console.log(`  Result: ${result}`);
    console.log(`  Status: ${isValid ? '✅ PASS' : '❌ FAIL'}\n`);

    if (!isValid) allPassed = false;
  }

  return allPassed;
}

// Check for canary values
function checkForCanaryValues(env) {
  console.log('=== Canary Value Detection ===\n');

  const canaryFields = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID', 
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ];

  let foundCanary = false;

  for (const field of canaryFields) {
    const value = env[field];
    if (value && value.includes('CANARY')) {
      console.log(`⚠️  ${field} contains 'CANARY' marker: ${value}`);
      foundCanary = true;
    }
  }

  if (!foundCanary) {
    console.log('No CANARY markers found in credentials');
  } else {
    console.log('\nThese credentials are explicitly marked as test/canary values');
    console.log('and should not be used in production systems.');
  }

  return foundCanary;
}

// Main execution
function main() {
  console.log('Testing credentials from .env.test\n');

  const env = loadEnvFile(path.resolve('./.env.test'));

  if (Object.keys(env).length === 0) {
    console.error('Failed to load environment variables from .env.test');
    return;
  }

  console.log('Loaded environment variables:');
  for (const [key, value] of Object.entries(env)) {
    console.log(`  ${key}=${value}`);
  }
  console.log('');

  const formatsValid = testCredentialFormats(env);
  const hasCanary = checkForCanaryValues(env);

  console.log('=== Final Assessment ===\n');

  if (hasCanary) {
    console.log('🔍 CONCLUSION: These are definitely test/canary credentials');
    console.log('   The CANARY markers confirm they are intentionally invalid');
    console.log('   and designed to detect unauthorized access or exfiltration.');
  } else if (formatsValid) {
    console.log('⚠️  WARNING: All credentials appear to have valid format');
    console.log('   However, given the file comments, these are likely still test values');
    console.log('   that happen to conform to expected formats.');
  } else {
    console.log('❌ CONCLUSION: Credentials have invalid format');
    console.log('   Combined with the file comments, these are clearly test values.');
  }

  console.log('\n💡 RECOMMENDATION: Do not use these credentials in any');
  console.log('   real application or production environment.');
}

main();

