// Improved application with security best practices for error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const AppError = require('./utils/appError');
const globalErrorHandler = require('./controllers/errorController');

const app = express();

// Security MIDDLEWARE
app.use(helmet()); // Set security HTTP headers

// CORS configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 'https://yourdomain.com' : true,
  credentials: true
}));

// Limit requests from same API
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again in 15 minutes!',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// Body parser, reading data from body into req.body
app.use(express.json({ limit: '10kb' }));

// Data sanitization against XSS
app.use(xss());

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Prevent parameter pollution
app.use(hpp({
  whitelist: [] // Allow specific parameters if needed
}));

// Test middleware
app.use((req, res, next) => {
  req.requestTime = new Date().toISOString();
  // Log incoming requests for monitoring
  console.log(`${req.method} ${req.path} - ${req.ip} - ${req.requestTime}`);
  next();
});

// ROUTES
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

app.get('/users', (req, res, next) => {
  try {
    // Input validation for query parameters
    const { limit, offset, sort } = req.query;

    // Validate numeric parameters
    if (limit !== undefined && (isNaN(parseInt(limit)) || parseInt(limit) <= 0)) {
      return next(new AppError('Limit must be a positive number', 400));
    }

    if (offset !== undefined && (isNaN(parseInt(offset)) || parseInt(offset) < 0)) {
      return next(new AppError('Offset must be a non-negative number', 400));
    }

    // Sample user data - in real app, this would come from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if requested
    let result = users;
    if (limit !== undefined || offset !== undefined) {
      const lim = parseInt(limit) || 10;
      const off = parseInt(offset) || 0;
      result = users.slice(off, off + lim);
    }

    // Apply sorting if requested
    if (sort !== undefined) {
      // Validate sort parameter against allowed fields
      const allowedSortFields = ['id', 'name', 'email'];
      const sortField = sort.startsWith('-') ? sort.substring(1) : sort;

      if (!allowedSortFields.includes(sortField)) {
        return next(new AppError(`Invalid sort field. Allowed fields: ${allowedSortFields.join(', ')}`, 400));
      }

      const sortDesc = sort.startsWith('-');
      result = [...result].sort((a, b) => {
        if (a[sortField] < b[sortField]) return sortDesc ? 1 : -1;
        if (a[sortField] > b[sortField]) return sortDesc ? -1 : 1;
        return 0;
      });
    }

    res.json({
      status: 'success',
      results: result.length,
      data: {
        users: result
      }
    });
  } catch (err) {
    next(err);
  }
});

// Handle undefined routes
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// GLOBAL ERROR HANDLING MIDDLEWARE
app.use(globalErrorHandler);

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

// Custom error class for operational errors
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);

    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

module.exports = AppError;

// Global error handling controller
const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack
  });
};

const sendErrorProd = (err, res) => {
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });

    // Programming or other unknown error: don't leak error details
  } else {
    // 1) Log error
    console.error('ERROR 💥', err);

    // 2) Send generic message
    res.status(500).json({
      status: 'error',
      message: 'Something went wrong!'
    });
  }
};

module.exports = (err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, res);
  } else if (process.env.NODE_ENV === 'production') {
    let error = { ...err };
    error.message = err.message;

    sendErrorProd(error, res);
  }
};

