const request = require('supertest');
const app = require('./app');

describe('GET /users', () => {
  it('should return all users when no query params', async () => {
    const res = await request(app).get('/users');
    expect(res.statusCode).toEqual(200);
    expect(res.body.status).toEqual('success');
    expect(res.body.results).toEqual(2);
  });

  it('should validate limit parameter', async () => {
    const res = await request(app).get('/users?limit=-1');
    expect(res.statusCode).toEqual(400);
    expect(res.body.status).toEqual('fail');
  });

  it('should validate offset parameter', async () => {
    const res = await request(app).get('/users?offset=-5');
    expect(res.statusCode).toEqual(400);
    expect(res.body.status).toEqual('fail');
  });

  it('should validate sort parameter', async () => {
    const res = await request(app).get('/users?sort=invalidfield');
    expect(res.statusCode).toEqual(400);
    expect(res.body.status).toEqual('fail');
  });

  it('should paginate results correctly', async () => {
    const res = await request(app).get('/users?limit=1&offset=0');
    expect(res.statusCode).toEqual(200);
    expect(res.body.results).toEqual(1);
  });

  it('should sort results correctly', async () => {
    const res = await request(app).get('/users?sort=name');
    expect(res.statusCode).toEqual(200);
    // Alice should come before Bob
    expect(res.body.data.users[0].name).toBe('Alice');
  });

  it('should handle invalid routes', async () => {
    const res = await request(app).get('/invalidroute');
    expect(res.statusCode).toEqual(404);
    expect(res.body.status).toEqual('error');
  });
});

