/**
 * Test script to validate credentials in .env.test
 * 
 * NOTE: Based on the "CANARY" values and comments in .env.test,
 * these appear to be synthetic/test credentials designed to detect
 * unauthorized access rather than actual working credentials.
 */

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('🔍 Testing database connection...');

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  // Check if this is a canary value
  if (databaseUrl.includes('CANARY')) {
    console.log('⚠️  DATABASE_URL appears to be a synthetic/test value (contains CANARY)');
    console.log('   This is likely intentional for security monitoring purposes');
    return false;
  }

  try {
    const client = new Client({ connectionString: databaseUrl });
    await client.connect();
    await client.query('SELECT NOW()');
    await client.end();
    console.log('✅ Database connection successful');
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

async function testAwsCredentials() {
  console.log('\n🔍 Testing AWS credentials...');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  // Check if these are canary values
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    console.log('⚠️  AWS credentials appear to be synthetic/test values (contain CANARY)');
    console.log('   This is likely intentional for security monitoring purposes');
    return false;
  }

  try {
    // Configure AWS SDK
    AWS.config.update({
      accessKeyId: accessKeyId,
      secretAccessKey: secretAccessKey,
      region: 'us-east-1' // Default region
    });

    // Try to make a simple API call (list S3 buckets)
    const s3 = new AWS.S3();
    const data = await s3.listBuckets().promise();
    console.log('✅ AWS credentials valid (able to list S3 buckets)');
    return true;
  } catch (error) {
    console.log('❌ AWS credentials validation failed:', error.message);
    return false;
  }
}

async function testAnthropicApiKey() {
  console.log('\n🔍 Testing Anthropic API key...');

  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  // Check if this is a canary value
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  Anthropic API key appears to be a synthetic/test value (contains CANARY)');
    console.log('   This is likely intentional for security monitoring purposes');
    return false;
  }

  try {
    // Make a minimal request to test the API key
    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-3-haiku-20240307',
        max_tokens: 1,
        messages: [{ role: 'user', content: 'Hi' }]
      },
      {
        headers: {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        timeout: 5000
      }
    );

    if (response.status === 200) {
      console.log('✅ Anthropic API key appears valid');
      return true;
    } else {
      console.log('❌ Unexpected response from Anthropic API:', response.status);
      return false;
