// Improved Express.js application with enhanced error handling, input validation, and security best practices

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.originalUrl} ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// Input validation middleware
const validateUserQuery = (req, res, next) => {
  const { limit, offset, search } = req.query;

  // Validate limit parameter
  if (limit !== undefined) {
    const limitNum = parseInt(limit, 10);
    if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Limit must be a positive integer between 1 and 100'
      });
    }
    req.query.limit = limitNum;
  }

  // Validate offset parameter
  if (offset !== undefined) {
    const offsetNum = parseInt(offset, 10);
    if (isNaN(offsetNum) || offsetNum < 0) {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Offset must be a non-negative integer'
      });
    }
    req.query.offset = offsetNum;
  }

  // Sanitize search parameter (additional XSS protection)
  if (search !== undefined) {
    if (typeof search !== 'string' || search.length > 50) {
      return res.status(400).json({
        error: 'Validation failed',
        message: 'Search must be a string with maximum length of 50 characters'
      });
    }
    // Basic sanitization - in practice, use a dedicated library
    req.query.search = search.trim();
  }

  next();
};

// Health check endpoint with error handling
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to retrieve health status'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validateUserQuery, (req, res) => {
  try {
    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply pagination
    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        limit,
        offset,
        hasMore: offset + limit < filteredUsers.length
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to retrieve users'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Global error handler:', error);

  // Default to 500 if no status code is set
  const statusCode = res.statusCode !== 200 ? res.statusCode : 500;

  res.status(statusCode).json({
    error: {
      message: process.env.NODE_ENV === 'production' 
        ? 'Internal server error' 
        : error.message,
      // Include stack trace only in development
      ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
    }
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

module.exports = app;

