/**
 * Test suite for the improved Express.js application
 * Demonstrates testing of validation and error handling
 */

const request = require('supertest');
const app = require('./app');

describe('Express App Security Improvements', () => {
  let server;

  beforeAll(() => {
    server = app.listen(4000); // Use different port for testing
  });

  afterAll(() => {
    server.close();
  });

  describe('Health Endpoint', () => {
    test('should return 200 and status ok', async () => {
      const response = await request(server).get('/health');
      expect(response.status).toBe(200);
      expect(response.body.status).toBe('ok');
      expect(response.body).toHaveProperty('timestamp');
    });
  });

  describe('Users Endpoint Validation', () => {
    test('should return users with default pagination', async () => {
      const response = await request(server).get('/users');
      expect(response.status).toBe(200);
      expect(response.body.success).toBe(true);
      expect(Array.isArray(response.body.data)).toBe(true);
      expect(response.body.pagination).toHaveProperty('total');
    });

    test('should validate limit parameter', async () => {
      // Test invalid limit (too high)
      let response = await request(server).get('/users?limit=101');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');

      // Test invalid limit (negative)
      response = await request(server).get('/users?limit=-5');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');

      // Test valid limit
      response = await request(server).get('/users?limit=2');
      expect(response.status).toBe(200);
      expect(response.body.data.length).toBe(2);
    });

    test('should validate offset parameter', async () {
      // Test invalid offset (negative)
      let response = await request(server).get('/users?offset=-1');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');

      // Test valid offset
      response = await request(server).get('/users?offset=1&limit=2');
      expect(response.status).toBe(200);
    });

    test('should validate search parameter', async () => {
      // Test search that's too long
      let response = await request(server).get('/users?search=' + 'a'.repeat(51));
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');

      // Test valid search
      response = await request(server).get('/users?search=Ali');
      expect(response.status).toBe(200);
      // Should find Alice
      expect(response.body.data.some(user => user.name.includes('Ali'))).toBe(true);
    });
  });

  describe('Error Handling', () => {
    test('should handle 404 for unknown routes', async () => {
      const response = await request(server).get('/unknown-route');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not found');
    });

    test('should handle validation errors properly', async () => {
      const response = await request(server).get('/users?limit=invalid');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });
  });

  describe('Security Headers', () => {
    test('should set security headers', async () => {
      const response = await request(server).get('/health');
      // Helmet sets various headers - checking a few key ones
      expect(response.headers).toHaveProperty('x-content-type-options');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers).toHaveProperty('x-frame-options');
    });
  });
});

