// Secure Express.js application with proper error handling and validation

const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(xss()); // Sanitize user input from XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Custom request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset } = req.query;

    // Basic validation - ensure numeric values within reasonable bounds
    const parsedLimit = Math.min(Math.max(parseInt(limit) || 10, 1), 100);
    const parsedOffset = Math.max(parseInt(offset) || 0, 0);

    // Sample data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply pagination
    const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      status: 'success',
      count: paginatedUsers.length,
      data: paginatedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: users.length
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(400).json({ 
      status: 'error', 
      message: 'Invalid query parameters' 
    });
  }
});

// Example POST endpoint with comprehensive validation
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return res.status(400).json({ 
        status: 'error', 
        message: 'Name is required and must be a non-empty string' 
      });
    }

    if (!email || typeof email !== 'string' || !isValidEmail(email)) {
      return res.status(400).json({ 
        status: 'error', 
        message: 'Valid email is required' 
      });
    }

    // Sanitize inputs
    const sanitizedName = name.trim();
    const sanitizedEmail = email.trim().toLowerCase();

    // In a real application, you would save to database here
    const newUser = {
      id: Date.now(), // Simple ID generation for demo
      name: sanitizedName,
      email: sanitizedEmail
    };

    res.status(201).json({
      status: 'success',
      message: 'User created successfully',
      data: newUser
    });

  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Helper function for email validation
function isValidEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
}

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    status: 'error', 
    message: 'Route not found' 
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
