      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    // Apply pagination
    const paginatedUsers = users.slice(parsedOffset, Math.min(parsedOffset + parsedLimit, users.length));

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: users.length,
        hasMore: parsedOffset + parsedLimit < users.length
      }
    });
  } catch (error) {
