/**
 * Verification script to check if credentials in .env.test are still valid
 * Tests connectivity to services using the provided credentials
 */

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in .env.test');
    return false;
  }

  try {
    const pool = new Pool({ connectionString: process.env.DATABASE_URL });
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    await pool.end();
    console.log('✅ Database connection successful');
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

async function testAWSCredentials() {
  console.log('\nTesting AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in .env.test');
    return false;
  }

  try {
    // Configure AWS SDK
    AWS.config.update({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1' // Default region for testing
    });

    // Try to list S3 buckets (requires minimal permissions)
    const s3 = new AWS.S3();
    const data = await s3.listBuckets().promise();
    console.log('✅ AWS credentials valid (able to list S3 buckets)');
    return true;
  } catch (error) {
    // Check if it's an authorization error vs connectivity error
    if (error.code === 'AccessDenied' || error.code === 'InvalidAccessKeyId' || error.code === 'SignatureDoesNotMatch') {
      console.log('❌ AWS credentials invalid:', error.code);
    } else {
      console.log('⚠️  AWS connectivity issue (credentials may be valid but no permissions/network):', error.message);
      // Still return true if it's not a credential error
      return !(error.code === 'AccessDenied' || error.code === 'InvalidAccessKeyId' || error.code === 'SignatureDoesNotMatch');
    }
    return false;
  }
}

async function testAnthropicAPI() {
  console.log('\nTesting Anthropic API key...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in .env.test');
    return false;
  }

  try {
    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-instant-1.2',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'Hi' }]
      },
      {
        headers: {
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        }
      }
    );

    if (response.status === 200 && response.data.content) {
      console.log('✅ Anthropic API key valid');
      return true;
    } else {
      console.log('❌ Anthropic API returned unexpected response');
      return false;
    }
  } catch (error) {
    if (error.response) {
      console.log('❌ Anthropic API key invalid:', error.response.status, error.response.data?.error?.message || error.response.data);
    } else {
      console.log('❌ Anthropic API connection failed:', error.message);
    }
    return false;
  }
}

async function testStripeAPI() {
  console.log('\nTesting Stripe API key...');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found in .env.test');
    return false;
  }

  try {
    const response = await axios.get(
      'https://api.stripe.com/v1/account',
      {
        auth: {
          username: process.env.STRIPE_SECRET_KEY,
          password: '' // Stripe uses username as key, empty password
        }
      }
    );

    if (response.status === 200) {
      console.log('✅ Stripe API key valid');
      return true;
    } else {
      console.log('❌ Stripe API returned unexpected response:', response.status);
      return false;
    }
  } catch (error) {
    if (error.response) {
      console.log('❌ Stripe API key invalid:', error.response.status, error.response.data?.error?.message || error.response.data);
    } else {
      console.log('❌ Stripe API connection failed:', error.message);
    }
    return false;
  }
}

async function testLogfire() {
  console.log('\nTesting Logfire token...');

  if (!process.env.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not found in .env.test');
    return false;
  }

  // Logfire doesn't have a simple public API to test tokens with
  // We'll do a basic format check
  if (process.env.LOGFIRE_TOKEN.length < 10) {
    console.log('❌ Logfire token appears too short');
    return false;
  }

  console.log('⚠️  Logfire token present (no validation endpoint available for testing)');
  console.log('   Note: Logfire validation would require sending telemetry data');
  return true; // Assume valid if present and reasonable length
}

async function main() {
  console.log('=== Credential Verification Script ===\n');
  console.log('Testing credentials from .env.test file...\n');

  const results = [];

  // Test each service
  results.push(await testDatabaseConnection());
  results.push(await testAWSCredentials());
  results.push(await testAnthropicAPI());
  results.push(await testStripeAPI());
  results.push(await testLogfire());

  // Summary
  const passed = results.filter(Boolean).length;
  const total = results.length;

  console.log(`\n=== Summary ===\n`);
  console.log(`${passed}/${total} credential checks passed`);

  if (passed === total) {
    console.log('🎉 All credentials appear to be valid!');
    process.exit(0);
  } else {
    console.log('⚠️  Some credentials may be invalid or expired');
    process.exit(1);
  }
}

// Check if required packages are installed, if not, install them
const requiredPackages = ['dotenv', 'pg', 'aws-sdk', 'axios'];
const missingPackages = [];

for (const pkg of requiredPackages) {
  try {
    require.resolve(pkg);
  } catch (e) {
    missingPackages.push(pkg);
  }
}

if (missingPackages.length > 0) {
  console.log(`Installing missing packages: ${missingPackages.join(', ')}`);
