  } catch (error) {
    console.log('Failed to install packages. Please install manually:');
    console.log(`npm install ${missingPackages.join(' ')}`);
    process.exit(1);
  }
}

// Run the verification
main().catch(error => {
  console.error('Unexpected error during verification:', error);
  process.exit(1);
});

/**
 * Simple verification script to check if credentials in .env.test have valid format
 * Does not actually connect to services (to avoid dependency issues)
 */

const fs = require('fs');
const path = require('path');

function loadEnvFile(filePath) {
  const envPath = path.resolve(filePath);
  if (!fs.existsSync(envPath)) {
    console.log(`.env file not found at ${envPath}`);
    return {};
  }

  const content = fs.readFileSync(envPath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=');
      envVars[key.trim()] = value.replace(/^["']|["']$/g, ''); // Remove quotes
    }
  });

  return envVars;
}

function validateDatabaseURL(url) {
  if (!url) return { valid: false, reason: 'Missing DATABASE_URL' };

  // Basic postgres URL format validation
  const postgresPattern = /^postgres(?:ql)?:\/\/.+:.+@.+:\d+\/.+$/;
  if (!postgresPattern.test(url)) {
    return { valid: false, reason: 'Invalid postgres URL format' };
  }

  // Check if it contains canary values (which might indicate test/fake data)
  if (url.includes('CANARY')) {
    return { valid: true, reason: 'Contains CANARY marker - likely test credentials', isCanary: true };
  }

  return { valid: true, reason: 'Valid postgres URL format' };
}

function validateAWSKey(key) {
  if (!key) return { valid: false, reason: 'Missing AWS_ACCESS_KEY_ID' };

  // AWS access key ID format: 20 characters, uppercase alphanumeric
  if (!/^[A-Z0-9]{20}$/.test(key)) {
    return { valid: false, reason: 'Invalid AWS access key ID format' };
  }

  if (key.includes('CANARY')) {
    return { valid: true, reason: 'Contains CANARY marker - likely test credentials', isCanary: true };
  }

  return { valid: true, reason: 'Valid AWS access key ID format' };
}

function validateAWSSecret(key) {
  if (!key) return { valid: false, reason: 'Missing AWS_SECRET_ACCESS_KEY' };

  // AWS secret key format: 40 characters, alphanumeric and punctuation
  if (key.length < 20) {
    return { valid: false, reason: 'AWS secret key too short' };
  }

  if (key.includes('CANARY')) {
    return { valid: true, reason: 'Contains CANARY marker - likely test credentials', isCanary: true };
  }

  return { valid: true, reason: 'AWS secret key present and reasonable length' };
}

function validateAPIKey(key, serviceName) {
  if (!key) return { valid: false, reason: `Missing ${serviceName}_API_KEY` };

  if (key.length < 10) {
    return { valid: false, reason: `${serviceName} API key too short` };
  }

  if (key.includes('CANARY')) {
    return { valid: true, reason: `Contains CANARY marker - likely test ${serviceName} credentials`, isCanary: true };
  }

  return { valid: true, reason: `${serviceName} API key present and reasonable length` };
}

function validateStripeKey(key) {
  if (!key) return { valid: false, reason: 'Missing STRIPE_SECRET_KEY' };

  // Stripe secret keys start with sk_live_ or sk_test_
  if (!/^sk_(live|test)_/.test(key)) {
    return { valid: false, reason: 'Invalid Stripe secret key format (should start with sk_live_ or sk_test_)' };
  }

  if (key.includes('CANARY')) {
    return { valid: true, reason: 'Contains CANARY marker - likely test credentials', isCanary: true };
  }

  return { valid: true, reason: 'Valid Stripe secret key format' };
}

