    process.exit(1);
  }

  console.log(`Found ${Object.keys(envVars).length} environment variables\n`);

  // Define validation tests
  const tests = [
    { name: 'DATABASE_URL', value: envVars.DATABASE_URL, validator: validateDatabaseURL },
    { name: 'AWS_ACCESS_KEY_ID', value: envVars.AWS_ACCESS_KEY_ID, validator: validateAWSKey },
