    const status = result.valid ? '✅' : '❌';
    const canaryNote = result.isCanary ? ' (CANARY/test credential)' : '';

    console.log(`${status} ${test.name}: ${result.reason}${canaryNote}`);

    if (result.valid) {
      passed++;
    }
  });

  console.log(`\n=== Summary ===\n`);
  console.log(`${passed}/${total} credential format checks passed`);

  // Check for required app variables that are missing
  const requiredAppVars = ['ALLOWED_ORIGINS', 'NODE_ENV', 'PORT'];
