```javascript
// Enhanced application with improved error handling, input validation, and security
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const { celebrate, Segments, Joi } = require('celebrate');
const AppError = require('./utils/appError');
const globalErrorHandler = require('./controllers/errorController');

const app = express();

// Security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

// Enable CORS with proper configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 'https://yourdomain.com' : true,
  credentials: true,
}));

// Limit requests from same IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against XSS
app.use(xss());

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Prevent parameter pollution
app.use(hpp({
  whitelist: [] // Add fields that you want to allow duplicates for
}));

// Health check endpoint with validation
app.get(
  '/health',
  celebrate({
    [Segments.QUERY]: Joi.object({
      detailed: Joi.boolean().optional(),
      timestamp: Joi.boolean().default(true)
    })
  }),
  (req, res, next) => {
    try {
      const response = { status: 'ok' };

      if (req.query.timestamp !== false) {
        response.timestamp = new Date().toISOString();
      }

      if (req.query.detailed) {
        response.uptime = process.uptime();
        response.memoryUsage = process.memoryUsage();
      }

      res.json(response);
    } catch (err) {
      next(err);
    }
  }
);

// Users endpoint with proper validation and error handling
app.get(
  '/users',
  celebrate({
    [Segments.QUERY]: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
      offset: Joi.number().integer().min(0).default(0),
      sort: Joi.string().valid('name', 'email', 'id').default('id'),
      order: Joi.string().valid('asc', 'desc').default('asc'),
      search: Joi.string().max(50).allow('')
    })
  }),
  (req, res, next) => {
    try {
      // In a real app, this would come from a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ];

      // Apply search filter if provided
      let filteredUsers = users;
      if (req.query.search) {
        const searchTerm = req.query.search.toLowerCase();
        filteredUsers = users.filter(user =>
          user.name.toLowerCase().includes(searchTerm) ||
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Apply sorting
      const sortedUsers = [...filteredUsers].sort((a, b) => {
        if (a[req.query.sort] < b[req.query.sort]) return req.query.order === 'asc' ? -1 : 1;
        if (a[req.query.sort] > b[req.query.sort]) return req.query.order === 'asc' ? 1 : -1;
        return 0;
      });

      // Apply pagination
      const paginatedUsers = sortedUsers.slice(
        req.query.offset,
        req.query.offset + req.query.limit
      );

      res.json({
        count: paginatedUsers.length,
        total: filteredUsers.length,
        limit: req.query.limit,
        offset: req.query.offset,
        users: paginatedUsers
      });
    } catch (err) {
      next(err);
    }
  }
);

// 404 handler for undefined routes
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// Global error handling middleware
app.use(globalErrorHandler);

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

### Supporting Files Needed:

To implement the above improvements, you would need to create these supporting files:

1. **utils/appError.js** - Custom error class:
```javascript
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

module.exports = AppError;
```

2. **controllers/errorController.js** - Global error handler:
```javascript
const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack
  });
};

const sendErrorProd = (err, res) => {
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });

    // Programming or other unknown error: don't leak error details
  } else {
    // Log error for developers
    console.error('ERROR 💥', err);

    // Send generic message
    res.status(500).json({
      status: 'error',
      message: 'Something went wrong!'
    });
  }
};

module.exports = (err, req, res, next) => {
  // Set defaults
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, res);
  } else if (process.env.NODE_ENV === 'production') {
    let error = { ...err };
    error.message = err.message;

    sendErrorProd(error, res);
  }
};
```

### Key Security Improvements Explained:

1. **Helmet.js**: Sets various HTTP headers to protect against common web vulnerabilities
2. **Rate Limiting**: Prevents brute force and DDoS attacks by limiting requests per IP
3. **Input Validation**: Uses Joi validation through celebrate to validate all inputs
4. **Sanitization**: 
   - XSS protection with xss-clean
   - NoSQL injection prevention with mongo-sanitize
   - Parameter pollution prevention with hpp
5. **CORS Configuration**: Properly configured Cross-Origin Resource Sharing
6. **Request Size Limits**: Prevents payload-based attacks
7. **Structured Error Handling**: 
   - Custom AppError class for operational errors
   - Global error handler that differentiates between dev/prod environments
   - Proper 404 handling
8. **Enhanced Endpoints**:
   - Health check with optional detailed information
   - Users endpoint with pagination, sorting, searching, and validation

### Additional Recommendations:

1. **Environment Configuration**: Use environment variables for secrets and configuration
2. **Logging**: Implement proper logging (e.g., with Winston or Morgan)
3. **Authentication/Authorization**: Add auth middleware for protected routes
4. **Database Connection Handling**: Proper error handling for database connections
5. **Process Management**: Handle uncaught exceptions and unhandled rejections
6. **Security-scanner Integration**: Regular dependency scanning with tools like npm audit or Snyk
7. **API Documentation**: Use Swagger/OpenAPI for API documentation
8. **Testing**: Add unit and integration tests for validation and error handling

These improvements transform the basic Express application into a production-ready service with proper security controls, input validation, and error handling mechanisms.

