// Test script to verify credentials in .env.test
// Load environment variables from .env.test
const fs = require('fs');
const path = require('path');

// Function to parse .env file
function parseEnvFile(filePath) {
  const envVars = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (!line || line.startsWith('#')) return;

      // Parse KEY=VALUE format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        // Remove quotes if present
        let value = match[2].trim();
        if (value.startsWith('"') && value.endsWith('"')) {
          value = value.slice(1, -1);
        } else if (value.startsWith("'") && value.endsWith("'")) {
          value = value.slice(1, -1);
        }
        envVars[key] = value;
      }
    });
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
  }
  return envVars;
}

// Load .env.test file
const envVars = parseEnvFile(path.resolve(__dirname, '.env.test'));

console.log('=== Testing Credentials from .env.test ===\n');

// Test Database Connection
if (envVars.DATABASE_URL) {
  console.log('1. Testing Database Connection:');
  console.log(`   DATABASE_URL: ${envVars.DATABASE_URL.replace(/:[^:@]+@/, ':***@')}`); // Hide password

  // Parse the database URL to extract connection details
  try {
    const url = new URL(envVars.DATABASE_URL);
    console.log(`   Host: ${url.hostname}:${url.port || 5432}`);
    console.log(`   Database: ${url.pathname.substring(1)}`);
    console.log(`   Username: ${url.username}`);
    console.log('   Status: ✓ Format valid (would need pg package to test actual connection)');

    // Note: Actual connection test would require:
    // const { Client } = require('pg');
    // const client = new Client({ connectionString: envVars.DATABASE_URL });
    // await client.connect();
    // await client.end();
  } catch (error) {
    console.log('   Status: ✗ Invalid URL format');
    console.log(`   Error: ${error.message}`);
  }
  console.log();
} else {
  console.log('1. Database Connection: ❌ DATABASE_URL not found\n');
}

// Test AWS Credentials
if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
  console.log('2. Testing AWS Credentials:');
  console.log(`   AWS_ACCESS_KEY_ID: ${envVars.AWS_ACCESS_KEY_ID.substring(0, 4)}...${envVars.AWS_ACCESS_KEY_ID.slice(-4)}`);
  console.log(`   AWS_SECRET_ACCESS_KEY: ${envVars.AWS_SECRET_ACCESS_KEY.substring(0, 4)}...${envVars.AWS_SECRET_ACCESS_KEY.slice(-4)}`);
  console.log('   Status: ✓ Format appears valid');
  console.log('   Note: Actual validation would require AWS SDK and permissions check');
  console.log();
} else {
  console.log('2. AWS Credentials: ❌ Missing AWS credentials\n');
}

// Test Anthropic API Key
if (envVars.ANTHROPIC_API_KEY) {
  console.log('3. Testing Anthropic API Key:');
  console.log(`   ANTHROPIC_API_KEY: ${envVars.ANTHROPIC_API_KEY.substring(0, 10)}...${envVars.ANTHROPIC_API_KEY.slice(-10)}`);

  // Basic format validation
  if (envVars.ANTHROPIC_API_KEY.startsWith('sk-ant-')) {
    console.log('   Status: ✓ Format appears valid (starts with sk-ant-)');
  } else {
    console.log('   Status: ⚠️  Format unusual (does not start with sk-ant-)');
  }

  console.log('   Note: Actual validation would require API call to Anthropic service');
  console.log();
} else {
  console.log('3. Anthropic API Key: ❌ ANTHROPIC_API_KEY not found\n');
}

// Test Stripe Secret Key
if (envVars.STRIPE_SECRET_KEY) {
  console.log('4. Testing Stripe Secret Key:');
  console.log(`   STRIPE_SECRET_KEY: ${envVars.STRIPE_SECRET_KEY.substring(0, 10)}...${envVars.STRIPE_SECRET_KEY.slice(-10)}`);

  // Basic format validation
  if (envVars.STRIPE_SECRET_KEY.startsWith('sk_live_') || envVars.STRIPE_SECRET_KEY.startsWith('sk_test_')) {
    console.log('   Status: ✓ Format appears valid (starts with sk_live_ or sk_test_)');
    if (envVars.STRIPE_SECRET_KEY.startsWith('sk_live_')) {
      console.log('   ⚠️  Warning: This appears to be a LIVE secret key');
    }
  } else {
    console.log('   Status: ⚠️  Format unusual (does not start with sk_live_ or sk_test_)');
  }

  console.log('   Note: Actual validation would require API call to Stripe service');
  console.log();
} else {
  console.log('4. Stripe Secret Key: ❌ STRIPE_SECRET_KEY not found\n');
}

// Test Logfire Token
if (envVars.LOGFIRE_TOKEN) {
  console.log('5. Testing Logfire Token:');
  console.log(`   LOGFIRE_TOKEN: ${envVars.LOGFIRE_TOKEN.substring(0, 10)}...${envVars.LOGFIRE_TOKEN.slice(-10)}`);

  // Basic format validation
  if (envVars.LOGFIRE_TOKEN.startsWith('CANARY-')) {
    console.log('   Status: ✓ Format matches canary pattern');
  } else {
    console.log('   Status: ⚠️  Format does not match expected canary pattern');
  }

  console.log('   Note: Actual validation would require API call to Logfire service');
  console.log();
} else {
  console.log('5. Logfire Token: ❌ LOGFIRE_TOKEN not found\n');
}

console.log('=== Summary ===');
console.log('These credentials appear to be formatted correctly but are marked as "CANARY" values.');
console.log('Canary tokens are typically designed to:');
console.log('1. Look like real credentials');
console.log('2. Trigger alerts if used (honeytokens)');
console.log('3. Indicate a security breach if accessed');
console.log('');
console.log('Recommendation: Do NOT attempt to use these credentials for actual API calls as they may:');
console.log('- Be invalid/revoked');
console.log('- Trigger security alerts');
console.log('- Be associated with monitoring/honeytoken systems');
console.log('');
console.log('For actual testing, use valid test credentials in a secure, isolated environment.');

