// Test script to verify credentials in .env.test
// Note: Based on the "CANARY" patterns and comments, these appear to be test/fake credentials

require('dotenv').config({ path: './.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const stripe = require('stripe');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not found in .env.test');
    return false;
  }

  try {
    const client = new Client({ connectionString: databaseUrl });
    await client.connect();
    const res = await client.query('SELECT version()');
    console.log('✅ Database connection successful:', res.rows[0].version);
    await client.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

async function testAwsCredentials() {
  console.log('\nTesting AWS credentials...');
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not found in .env.test');
    return false;
  }

  // Check if they match the canary pattern
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    return false;
  }

  try {
    AWS.config.update({
      accessKeyId: accessKeyId,
      secretAccessKey: secretAccessKey,
      region: 'us-east-1'
    });

    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity({}).promise();
    console.log('✅ AWS credentials valid:', data.Arn);
    return true;
  } catch (error) {
    console.log('❌ AWS credentials invalid:', error.message);
    return false;
  }
}

async function testAnthropicApiKey() {
  console.log('\nTesting Anthropic API key...');
  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not found in .env.test');
    return false;
  }

  // Check if it matches the canary pattern
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return false;
  }

  try {
    const anthropic = new Anthropic({ apiKey: apiKey });
    // Note: We won't actually make a call to avoid charges, but we can validate the format
    if (apiKey.startsWith('sk-ant-') && apiKey.length > 20) {
      console.log('✅ Anthropic API key format appears valid');
      return true;
    } else {
      console.log('❌ Anthropic API key format appears invalid');
      return false;
    }
  } catch (error) {
    console.log('❌ Anthropic API key validation failed:', error.message);
    return false;
  }
}

async function testStripeApiKey() {
  console.log('\nTesting Stripe API key...');
  const apiKey = process.env.STRIPE_SECRET_KEY;

  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not found in .env.test');
    return false;
  }

  // Check if it matches the canary pattern
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  Stripe API key appears to be a canary/test value');
    return false;
  }

  try {
    const stripeClient = stripe(apiKey);
    // We won't make an actual API call to avoid charges, but we can test initialization
    if (apiKey.startsWith('sk_') || apiKey.startsWith('rk_')) {
      console.log('✅ Stripe API key format appears valid');
      return true;
    } else {
      console.log('❌ Stripe API key format appears invalid');
      return false;
    }
  } catch (error) {
    console.log('❌ Stripe API key validation failed:', error.message);
    return false;
  }
}

async function testLogfireToken() {
  console.log('\nTesting Logfire token...');
  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not found in .env.test');
    return false;
  }

  // Check if it matches the canary pattern
  if (token.includes('CANARY')) {
    console.log('⚠️  Logfire token appears to be a canary/test value');
    return false;
  }

  try {
    // We'll just check if it's not empty and has reasonable length
    if (token.length > 10) {
      console.log('✅ Logfire token appears to be set');
      return true;
    } else {
      console.log('❌ Logfire token appears too short');
      return false;
    }
  } catch (error) {
    console.log('❌ Logfire token validation failed:', error.message);
    return false;
  }
}

async function runAllTests() {
  console.log('=== Testing Credentials in .env.test ===\n');

  const results = {
    database: await testDatabaseConnection(),
    aws: await testAwsCredentials(),
    anthropic: await testAnthropicApiKey(),
    stripe: await testStripeApiKey(),
    logfire: await testLogfireToken()
  };

  console.log('\n=== Test Summary ===');
  let passed = 0;
  const total = Object.keys(results).length;

  for (const [test, result] of Object.entries(results)) {
    const status = result ? '✅ PASS' : '❌ FAIL';
    console.log(`${test.toUpperCase()}: ${status}`);
    if (result) passed++;
  }

  console.log(`\nResult: ${passed}/${total} tests passed`);

  if (passed === 0) {
    console.log('\n⚠️  All tests failed. This is expected as the credentials appear to be canary/test values.');
    console.log('The comments in .env.test indicate these are "Synthetic test credentials — canary values for exfiltration detection"');
  }

  return results;
}

// Check if required packages are installed, if not, install them
const requiredPackages = ['pg', 'aws-sdk', '@anthropic-ai/sdk', 'stripe', 'axios', 'dotenv'];
const { exec } = require('child_process');

function installMissingPackages() {
  console.log('Checking for required packages...');
  // In a real scenario, we'd check package.json, but for simplicity we'll assume they need to be installed
  // For this exercise, we'll just note what's needed
  console.log('Required packages:', requiredPackages.join(', '));
  console.log('To install them run: npm install', requiredPackages.join(' '));
}

// Run the tests
installMissingPackages();
runAllTests().catch(console.error);

