const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors({
  origin: process.env.NODE_ENV === 'production' ? 'https://yourdomain.com' : '*',
  credentials: true
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Prevent parameter pollution
app.use(hpp());

// Request logging for monitoring and debugging
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path} - ${new Date().toISOString()} - IP: ${req.ip}`);
  next();
});

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  // Validate query parameters if any
  const { detailed } = req.query;

  if (detailed && detailed !== 'true' && detailed !== 'false') {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Query parameter "detailed" must be boolean'
    });
  }

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    ...(detailed === 'true' && { 
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    })
  });
});

// Users endpoint with improved security
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Validate limit parameter
    let parsedLimit = 10; // default
    if (limit !== undefined) {
      parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit <= 0 || parsedLimit > 100) {
        return res.status(400).json({
          error: 'Validation Error',
          message: 'Limit must be a number between 1 and 100'
        });
      }
    }

    // Validate offset parameter
    let parsedOffset = 0; // default
    if (offset !== undefined) {
      parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          error: 'Validation Error',
          message: 'Offset must be a non-negative number'
        });
      }
    }

    // Sanitize search parameter to prevent injection
    let sanitizedSearch = '';
    if (search !== undefined) {
      if (typeof search !== 'string' || search.length > 50) {
        return res.status(400).json({
          error: 'Validation Error',
          message: 'Search must be a string with maximum length of 50'
        });
      }
      // Basic sanitization - in real app, use proper escaping based on context
      sanitizedSearch = search.trim().replace(/[<>\'\"\\]/g, '');
    }

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (sanitizedSearch) {
      const lowerSearch = sanitizedSearch.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(lowerSearch) || 
        user.email.toLowerCase().includes(lowerSearch)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: filteredUsers.length,
        hasMore: parsedOffset + parsedLimit < filteredUsers.length
      }
    });

  } catch (error) {
    // Handle unexpected errors
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled Error:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // In production, don't leak stack traces
  const response = {
    error: err.message || 'Internal Server Error',
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  };

  // Add validation error details if available
  if (err.validationErrors) {
    response.validationErrors = err.validationErrors;
  }

  res.status(statusCode).json(response);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = { app, server };

