/**
 * Script to verify connectivity to services using credentials from .env.test
 * NOTE: This script makes actual network requests to external services.
 * Use with caution and ensure you have permission to test these endpoints.
 */

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const axios = require('axios');

// Load environment variables
const {
  DATABASE_URL,
  AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY,
