/**
 * Test database connectivity
 */
async function testDatabaseConnection() {
  if (!DATABASE_URL) {
    console.log('❌ DATABASE_URL not found');
    return false;
  }

  try {
    const pool = new Pool({ connectionString: DATABASE_URL });
    const client = await pool.connect();
    const res = await client.query('SELECT version()');
    console.log('✅ Database connection successful');
    console.log(`   PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
    client.release();
    await pool.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

/**
 * Test AWS credentials (basic validation - doesn't make actual API calls)
 * Note: Actual AWS API calls would require specific service endpoints
 */
function testAWSCredentials() {
  const hasAccessKey = AWS_ACCESS_KEY_ID && AWS_ACCESS_KEY_ID.length > 0;
  const hasSecretKey = AWS_SECRET_ACCESS_KEY && AWS_SECRET_ACCESS_KEY.length > 0;

  if (!hasAccessKey || !hasSecretKey) {
    console.log('❌ AWS credentials incomplete');
    return false;
  }

  // Basic format validation
  const accessKeyFormat = /^AKIA[0-9A-Z]{16}$/.test(AWS_ACCESS_KEY_ID);
  const secretKeyFormat = /^[0-9a-zA-Z\/+]{40}$/.test(AWS_SECRET_ACCESS_KEY);

