async function main() {
  console.log('='.repeat(60));
  print(env.NODE_ENV || 'development');
  console.log('='.repeat(60));

  const results = {
    database: await testDatabaseConnection(),
    aws: testAWSCredentials(),
    anthropic: await testAnthropicAPI(),
