    const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    // AWS Secret Access Key format: 40 characters of alphanumeric, slash, or plus
    const secretKeyPattern = /^[0-9a-zA-Z\/+]{40}$/;

    const accessKeyValid = accessKeyPattern.test(envVars.AWS_ACCESS_KEY_ID);
    const secretKeyValid = secretKeyPattern.test(envVars.AWS_SECRET_ACCESS_KEY);

    validationResults.aws = accessKeyValid && secretKeyValid;

