/**
 * Test script to verify credentials in .env.test
 * Checks database connectivity and API key validity
 */

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const fetch = require('node-fetch');

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in .env.test');
    return false;
  }

  try {
    const pool = new Pool({ connectionString: process.env.DATABASE_URL });
    const client = await pool.connect();
    const res = await client.query('SELECT version()');
    console.log('✅ Database connection successful');
    console.log(`   PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
    client.release();
    await pool.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

async function testAWS() {
  console.log('\nTesting AWS credentials...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in .env.test');
    return false;
  }

  // Note: We won't actually make AWS API calls as they might incur charges
  // Instead, we'll just verify the format looks correct
  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  const isValidFormat = 
    accessKeyId.startsWith('AKIA') && 
    accessKeyId.length === 20 &&
    secretAccessKey.length === 40;

  if (isValidFormat) {
    console.log('✅ AWS credentials format appears valid');
    console.log(`   Access Key ID: ${accessKeyId.substring(0, 4)}...${accessKeyId.substring(-4)}`);
    return true;
  } else {
    console.log('❌ AWS credentials format appears invalid');
    return false;
  }
}

async function testAnthropicAPI() {
  console.log('\nTesting Anthropic API key...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in .env.test');
    return false;
  }

  const apiKey = process.env.ANTHROPIC_API_KEY;

  // Basic format check
  if (!apiKey.startsWith('sk-ant-')) {
    console.log('❌ Anthropic API key format appears invalid');
    return false;
  }

  // We won't actually call the API to avoid potential charges
  // But we can verify it's not a placeholder
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return false;
  }

  console.log('✅ Anthropic API key format appears valid');
  return true;
}

