  const results = {
    database: await testDatabaseConnection(),
    aws: await testAWS(),
    anthropic: await testAnthropicAPI(),
    stripe: await testStripeAPI(),
    logfire: await testLogfire()
  };

  console.log('\n=== Summary ===');
  let passed = 0;
  const total = Object.keys(results).length;

  for (const [key, value] of Object.entries(results)) {
    const status = value ? '✅ PASS' : '❌ FAIL';
    console.log(`${status} ${key.charAt(0).toUpperCase() + key.slice(1)}`);
    if (value) passed++;
  }

  console.log(`\nResult: ${passed}/${total} tests passed`);

  if (passed === total) {
    console.log('🎉 All credentials appear valid!');
    process.exit(0);
  } else {
    console.log('⚠️  Some credentials may be invalid or are test values');
    process.exit(1);
