/**
 * Simple test script to verify credentials in .env.test
 * Without external dependencies for basic validation
 */

const fs = require('fs');
const path = require('path');

// Load .env.test file manually
function loadEnvFile(filePath) {
  const envVars = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (trimmedLine && !trimmedLine.startsWith('#')) {
        const [key, ...valueParts] = trimmedLine.split('=');
        if (key && valueParts.length > 0) {
          const value = valueParts.join('=');
          envVars[key.trim()] = value.trim();
        }
      }
    }
    return envVars;
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
    return {};
  }
}

function testDatabaseURL(url) {
  console.log('Testing DATABASE_URL format...');

  if (!url) {
    console.log('❌ DATABASE_URL not found');
    return false;
  }

  // Basic PostgreSQL URL format validation
  const pgUrlPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/.+$/;
  if (pgUrlPattern.test(url)) {
    console.log('✅ DATABASE_URL format appears valid');

    // Check if it contains canary values
    if (url.includes('CANARY')) {
      console.log('⚠️  DATABASE_URL contains canary/test values');
      return 'canary';
    }
    return true;
  } else {
    console.log('❌ DATABASE_URL format appears invalid');
    return false;
  }
}

function testAWSCredentials(accessKeyId, secretAccessKey) {
  console.log('\nTesting AWS credentials format...');

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not found');
    return false;
  }

  // AWS Access Key ID format: AKIA followed by 16 alphanumeric characters
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  // AWS Secret Access Key format: 40 alphanumeric characters
  const secretKeyPattern = /^[0-9a-zA-Z\+/]{40}$/;

  const accessKeyValid = accessKeyPattern.test(accessKeyId);
  const secretKeyValid = secretKeyPattern.test(secretAccessKey);

  if (accessKeyValid && secretKeyValid) {
    console.log('✅ AWS credentials format appears valid');

    // Check if they contain canary values
    if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
      console.log('⚠️  AWS credentials contain canary/test values');
      return 'canary';
    }
    return true;
  } else {
    console.log('❌ AWS credentials format appears invalid');
    if (!accessKeyValid) console.log(`   Access Key ID format invalid: ${accessKeyId}`);
    if (!secretKeyValid) console.log(`   Secret Access Key format invalid: ${secretAccessKey.substring(0, 4)}...`);
    return false;
  }
}

function testAPIKey(name, key, prefix) {
  console.log(`\nTesting ${name} API key format...`);

  if (!key) {
    console.log(`❌ ${name} API key not found`);
    return false;
  }

  if (!key.startsWith(prefix)) {
    console.log(`❌ ${name} API key format invalid (should start with ${prefix})`);
    return false;
  }

  console.log(`✅ ${name} API key format appears valid`);

  // Check if it contains canary values
  if (key.includes('CANARY')) {
    console.log(`⚠️  ${name} API key appears to be a canary/test value`);
    return 'canary';
  }
  return true;
}

function main() {
  console.log('=== Simple Credential Format Validation ===\n');

  // Load environment variables from .env.test
  const envVars = loadEnvFile('.env.test');

  if (Object.keys(envVars).length === 0) {
    console.log('❌ No environment variables found in .env.test');
    process.exit(1);
  }

  console.log(`Loaded ${Object.keys(envVars).length} environment variables from .env.test\n`);

  // Test each credential type
  const results = {};

  results.database = testDatabaseURL(envVars.DATABASE_URL);
  results.aws = testAWSCredentials(
    envVars.AWS_ACCESS_KEY_ID, 
    envVars.AWS_SECRET_ACCESS_KEY
  );
  results.anthropic = testAPIKey(
    'Anthropic', 
    envVars.ANTHROPIC_API_KEY, 
    'sk-ant-'
  );
  results.stripe = testAPIKey(
    'Stripe', 
    envVars.STRIPE_SECRET_KEY, 
    'sk_live_'
  );
  results.logfire = testAPIKey(
    'Logfire', 
    envVars.LOGFIRE_TOKEN, 
    ''  // No specific prefix check for Logfire
  );

  // Summary
  console.log('\n=== Summary ===');
  let passed = 0;
  const total = Object.keys(results).length;
  let hasCanary = false;

  for (const [key, value] of Object.entries(results)) {
    let status;
    if (value === true) {
      status = '✅ PASS';
      passed++;
    } else if (value === 'canary') {
      status = '⚠️  CANARY';
      hasCanary = true;
    } else {
      status = '❌ FAIL';
    }
    console.log(`${status} ${key.charAt(0).toUpperCase() + key.slice(1)}`);
  }

  console.log(`\nResult: ${passed}/${total} format checks passed`);

  if (hasCanary) {
    console.log('\n⚠️  WARNING: Some credentials appear to be canary/test values');
    console.log('   These should not be used in production environments');
  }

  if (passed === total && !hasCanary) {
    console.log('\n🎯 All credentials have valid format and appear to be real values');
    process.exit(0);
  } else if (passed === total && hasCanary) {
    console.log('\n⚠️  All credentials have valid format but appear to be test values');
    process.exit(0);
  } else {
