/**
 * Credential validation script
 * This script performs basic connectivity checks to verify if services are reachable
 * It does not validate the actual credentials, only checks if endpoints respond
 */

require('dotenv').config({ path: '.env.test' });
const https = require('https');
const { Client } = require('pg');

console.log('Starting credential validation...');
console.log('==============================\n');

// Helper function to make HTTPS requests
function makeRequest(options) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          data: data.substring(0, 200) + (data.length > 200 ? '...' : '') // Limit output
        });
      });
    });

    req.on('error', reject);
    req.end();
  });
}

// Test database connectivity
async function testDatabase() {
  console.log('🔍 Testing Database Connection...');

  if (!process.env.DATABASE_URL) {
    console.log('  ⚠️  DATABASE_URL not configured');
    return;
  }

  try {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    const res = await client.query('SELECT version()');
    await client.end();
    console.log('  ✅ Database connection successful');
    console.log(`  📊 PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
  } catch (error) {
    console.log('  ❌ Database connection failed');
    console.log(`  💥 Error: ${error.message.substring(0, 100)}...`);
  }
  console.log('');
}

// Test AWS STS (Security Token Service) - safe endpoint that doesn't incur charges
async function testAws() {
  console.log('🔍 Testing AWS Connectivity...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('  ⚠️  AWS credentials not configured');
    return;
  }

  // We'll make a simple request to AWS STS get-caller-identity
  // This is a safe operation that doesn't incur charges
  const date = new Date().toISOString().replace(/T/, ' ').replace(/\..+/, '');
  const service = 'sts';
  const region = 'us-east-1'; // Default region

  // This is a simplified signature check - in reality AWS v4 signing is complex
  // We're just checking if we can reach the endpoint
  const options = {
    hostname: 'sts.amazonaws.com',
    port: 443,
    path: '/?Action=GetCallerIdentity&Version=2011-06-15',
    method: 'GET',
    headers: {
      'Host': 'sts.amazonaws.com',
      'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8',
      'X-Amz-Date': new Date().toISOString().replace(/[:-]|\.\d{3}/g, ''),
      'Authorization': 'AWS4-HMAC-SHA256 Credential=*/20230101/us-east-1/sts/aws4_request, SignedHeaders=host;x-amz-date, Signature=example'
    }
  };

  try {
    const response = await makeRequest(options);
    // Even a 403 (Forbidden) means we reached the service
    if (response.statusCode === 403 || response.statusCode === 200 || response.statusCode === 400) {
      console.log('  ✅ AWS endpoint reachable');
      console.log(`  📊 HTTP Status: ${response.statusCode}`);
