function maskCredential(credential, showChars = 4) {
  if (!credential) return '<not set>';
  if (credential.length <= showChars * 2) return '*'.repeat(credential.length);
  return credential.substring(0, showChars) + '*'.repeat(credential.length - showChars * 2) + credential.substring(-showChars);
}

// Test each credential
function validateDatabaseUrl() {
  console.log('🔍 Checking DATABASE_URL format...');

  if (!process.env.DATABASE_URL) {
