// Manually parse .env.test file since we can't rely on dotenv being installed
function loadEnvFile(filename) {
  const fs = require('fs');
  const envVars = {};

  try {
    const content = fs.readFileSync(filename, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const lineTrimmed = line.trim();
      // Skip empty lines and comments
      if (lineTrimmed === '' || lineTrimmed.startsWith('#')) continue;

      const equalsIndex = lineTrimmed.indexOf('=');
      if (equalsIndex > 0) {
        const key = lineTrimmed.substring(0, equalsIndex).trim();
        const value = lineTrimmed.substring(equalsIndex + 1).trim();
        envVars[key] = value;
      }
    }
  } catch (error) {
    console.error(`Error reading ${filename}:`, error.message);
  }

  return envVars;
}

