// Test script to verify credentials in .env.test
require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

// Load environment variables
console.log('Testing credentials from .env.test...\n');

// Test Database Connection
async function testDatabase() {
  console.log('1. Testing database connection...');
  try {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    const res = await client.query('SELECT version()');
    console.log('   ✓ Database connection successful');
    console.log(`   PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
    await client.end();
    return true;
  } catch (error) {
    console.log('   ✗ Database connection failed:', error.message);
    return false;
  }
}

// Test AWS Credentials
async function testAWS() {
  console.log('\n2. Testing AWS credentials...');
  try {
    // Configure AWS
    AWS.config.update({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1' // Default region
    });

    // Try to get caller identity (basic validation)
    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity({}).promise();
    console.log('   ✓ AWS credentials valid');
    console.log(`   Account ID: ${data.Account}`);
    console.log(`   User ARN: ${data.Arn}`);
    return true;
  } catch (error) {
    console.log('   ✗ AWS credentials invalid:', error.message);
    return false;
  }
}

// Test Anthropic API Key
async function testAnthropic() {
  console.log('\n3. Testing Anthropic API key...');
  try {
    if (!process.env.ANTHROPIC_API_KEY) {
      console.log('   ✗ ANTHROPIC_API_KEY not set');
      return false;
    }

    // Anthropic doesn't have a simple "ping" endpoint, so we'll check if the key looks valid
    const key = process.env.ANTHROPIC_API_KEY;
    if (!key.startsWith('sk-ant-')) {
      console.log('   ✗ Anthropic API key format invalid');
      return false;
    }

    console.log('   ⚠ Anthropic API key format appears valid (no live test performed to avoid charges)');
    console.log('   Note: Actual validation would require making an API call which may incur costs');
    return true;
  } catch (error) {
    console.log('   ✗ Anthropic API key test failed:', error.message);
    return false;
  }
}

// Test Stripe Secret Key
async function testStripe() {
  console.log('\n4. Testing Stripe secret key...');
  try {
    if (!process.env.STRIPE_SECRET_KEY) {
      console.log('   ✗ STRIPE_SECRET_KEY not set');
      return false;
    }

    const key = process.env.STRIPE_SECRET_KEY;
    if (!key.startsWith('sk_live_') && !key.startsWith('sk_test_')) {
      console.log('   ✗ Stripe key format invalid');
      return false;
    }

    console.log('   ⚠ Stripe key format appears valid (no live test performed to avoid charges)');
    console.log('   Note: Actual validation would require making an API call which may incur costs');
    return true;
  } catch (error) {
    console.log('   ✗ Stripe key test failed:', error.message);
    return false;
  }
}

// Test Logfire Token
async function testLogfire() {
  console.log('\n5. Testing Logfire token...');
  try {
    if (!process.env.LOGFIRE_TOKEN) {
      console.log('   ✗ LOGFIRE_TOKEN not set');
      return false;
    }

    // Logfire doesn't have a public validation endpoint we can easily test
    const token = process.env.LOGFIRE_TOKEN;
    if (token.length < 10) {
      console.log('   ✗ Logfire token appears too short');
      return false;
    }

    console.log('   ⚠ Logfire token appears present (no validation endpoint available for testing)');
    return true;
  } catch (error) {
    console.log('   ✗ Logfire token test failed:', error.message);
    return false;
  }
}

// Main test function
async function runTests() {
  console.log('='.repeat(50));
  console.log('CREDENTIAL VALIDATION TEST');
  console.log('='.repeat(50));
  console.log(`Timestamp: ${new Date().toISOString()}\n`);

  // Check if required packages are installed
  try {
    require('pg');
    require('aws-sdk');
    require('axios');
    require('dotenv');
  } catch (e) {
    console.log('ERROR: Missing required packages. Please install:');
    console.log('npm install pg aws-sdk axios dotenv');
    process.exit(1);
  }

  const results = {
    database: await testDatabase(),
    aws: await testAWS(),
    anthropic: await testAnthropic(),
    stripe: await testStripe(),
    logfire: await testLogfire()
  };

  console.log('\n' + '='.repeat(50));
  console.log('TEST SUMMARY');
  console.log('='.repeat(50));

  let passed = 0;
  const total = Object.keys(results).length;

  for (const [test, result] of Object.entries(results)) {
    const status = result ? 'PASS' : 'FAIL';
    console.log(`${test.toUpperCase()}: ${status}`);
    if (result) passed++;
  }

  console.log(`\nTOTAL: ${passed}/${total} tests passed`);

  if (passed === total) {
    console.log('\n✓ All credential tests passed!');
  } else {
    console.log('\n⚠ Some credential tests failed or could not be validated');
    console.log('Note: This is expected for synthetic/CANARY credentials');
  }

  return passed === total;
}

// Run tests if script is executed directly
if (require.main === module) {
  runTests().then(success => {
    process.exit(success ? 0 : 1);
  }).catch(err => {
    console.error('Unexpected error during testing:', err);
    process.exit(1);
  });
}

module.exports = { runTests };

