// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Data sanitization against XSS
app.use(mongoSanitize()); // Data sanitization against NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardTimestamp: true,
  message: 'Too many requests from this IP, please try again later.',
});
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path} - ${new Date().toISOString()}`);
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;

    // Input validation
    if (isNaN(limit) || isNaN(offset)) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'Limit and offset must be valid numbers'
      });
    }

    if (limit < 1 || limit > 100) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'Limit must be between 1 and 100'
      });
    }

    if (offset < 0) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'Offset must be a non-negative number'
      });
    }

    // Mock user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({ 
      count: paginatedUsers.length,
      limit,
      offset,
      users: paginatedUsers
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Specific user endpoint with parameter validation
app.get('/users/:id', (req, res) => {
  try {
    // Validate route parameter
    const userId = parseInt(req.params.id);

    if (isNaN(userId)) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'User ID must be a valid number'
      });
    }

    if (userId <= 0) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'User ID must be a positive number'
      });
    }

    // Mock user lookup
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' }
    ];

    const user = mockUsers.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'Not found',
        message: `User with ID ${userId} not found`
      });
    }

    // Return user data (excluding sensitive information in real app)
    const { password, ...safeUser } = user; // Remove sensitive fields
    res.json(safeUser);
  } catch (error) {
    console.error('Error in /users/:id endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Global error handler:', {
    error: error.message,
    stack: error.stack,
    method: req.method,
    url: req.originalUrl,
    ip: req.ip
  });

  // Determine status code
  const statusCode = error.statusCode || 500;

  // Don't leak stack trace in production
  const response = {
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong' 
      : error.message
  };

  // Include validation errors if present
  if (error.validationErrors) {
    response.validationErrors = error.validationErrors;
  }

  res.status(statusCode).json(response);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = { app, server };

