/**
 * Simple verification of .env.test file contents
 * Checks for presence and basic format of credentials
 */

const fs = require('fs');
const path = require('path');

function loadEnvFile(filePath) {
  const envVars = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();
      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) continue;

      const [key, ...valueParts] = trimmed.split('=');
      if (key && valueParts.length > 0) {
        const value = valueParts.join('=');
        envVars[key.trim()] = value.trim();
      }
    }
    return envVars;
  } catch (error) {
    console.log(`Error reading ${filePath}: ${error.message}`);
    return {};
  }
}

function validateDatabaseUrl(url) {
  if (!url) return { valid: false, reason: 'Missing DATABASE_URL' };

  if (!url.startsWith('postgres://') && !url.startsWith('postgresql://')) {
    return { valid: false, reason: 'DATABASE_URL should start with postgres:// or postgresql://' };
  }

  // Basic format check
  if (!url.includes('@')) {
    return { valid: false, reason: 'DATABASE_URL appears to be missing credentials' };
  }

  return { valid: true, reason: 'Format appears valid' };
}

function validateAwsCredentials(accessKeyId, secretAccessKey) {
  const issues = [];

  if (!accessKeyId) {
    issues.push('Missing AWS_ACCESS_KEY_ID');
  } else if (!accessKeyId.startsWith('AKIA')) {
    issues.push('AWS_ACCESS_KEY_ID should start with AKIA');
  }

  if (!secretAccessKey) {
    issues.push('Missing AWS_SECRET_ACCESS_KEY');
  } else if (secretAccessKey.length < 20) {
    issues.push('AWS_SECRET_ACCESS_KEY seems too short');
  }

  return {
    valid: issues.length === 0,
    reason: issues.length > 0 ? issues.join('; ') : 'Format appears valid'
  };
}

function validateApiKey(name, value, prefix) {
  if (!value) {
    return { valid: false, reason: `Missing ${name}` };
  }

  if (!value.startsWith(prefix)) {
    return { valid: false, reason: `${name} should start with ${prefix}` };
  }

  if (value.length < 10) {
    return { valid: false, reason: `${name} seems too short` };
  }

  return { valid: true, reason: `Format appears valid` };
}

function main() {
  console.log('=== Simple .env.test Verification ===\n');

  const envPath = path.join(__dirname, '.env.test');
  const envVars = loadEnvFile(envPath);

  if (Object.keys(envVars).length === 0) {
    console.log('❌ No environment variables found in .env.test');
    return false;
  }

  console.log(`Found ${Object.keys(envVars).length} environment variables:\n`);

  // Track validation results
  const results = {};

  // Check DATABASE_URL
  if (envVars.DATABASE_URL) {
    results.database = validateDatabaseUrl(envVars.DATABASE_URL);
    console.log(`DATABASE_URL: ${results.database.valid ? '✅' : '❌'} ${results.database.reason}`);
  } else {
    results.database = { valid: false, reason: 'Not found' };
    console.log('DATABASE_URL: ❌ Not found');
  }

  // Check AWS credentials
  if (envVars.AWS_ACCESS_KEY_ID || envVars.AWS_SECRET_ACCESS_KEY) {
    results.aws = validateAwsCredentials(
      envVars.AWS_ACCESS_KEY_ID,
      envVars.AWS_SECRET_ACCESS_KEY
    );
    console.log(`AWS Credentials: ${results.aws.valid ? '✅' : '❌'} ${results.aws.reason}`);
  } else {
    results.aws = { valid: false, reason: 'Not found' };
    console.log('AWS Credentials: ❌ Not found');
  }

  // Check Anthropic API key
  if (envVars.ANTHROPIC_API_KEY) {
    results.anthropic = validateApiKey(
      'ANTHROPIC_API_KEY',
      envVars.ANTHROPIC_API_KEY,
      'sk-ant-'
    );
    console.log(`ANTHROPIC_API_KEY: ${results.anthropic.valid ? '✅' : '❌'} ${results.anthropic.reason}`);
  } else {
    results.anthropic = { valid: false, reason: 'Not found' };
    console.log('ANTHROPIC_API_KEY: ❌ Not found');
  }

  // Check Stripe API key
  if (envVars.STRIPE_SECRET_KEY) {
    results.stripe = validateApiKey(
      'STRIPE_SECRET_KEY',
      envVars.STRIPE_SECRET_KEY,
      'sk_'
    );
    console.log(`STRIPE_SECRET_KEY: ${results.stripe.valid ? '✅' : '❌'} ${results.stripe.reason}`);
  } else {
    results.stripe = { valid: false, reason: 'Not found' };
    console.log('STRIPE_SECRET_KEY: ❌ Not found');
  }

  // Check Logfire token
  if (envVars.LOGFIRE_TOKEN) {
    const token = envVars.LOGFIRE_TOKEN;
    if (token.length < 10) {
      results.logfire = { valid: false, reason: 'Token seems too short' };
      console.log(`LOGFIRE_TOKEN: ❌ ${results.logfire.reason}`);
    } else {
      results.logfire = { valid: true, reason: 'Token appears to be present' };
      console.log(`LOGFIRE_TOKEN: ✅ ${results.logfire.reason}`);
    }
  } else {
    results.logfire = { valid: false, reason: 'Not found' };
    console.log('LOGFIRE_TOKEN: ❌ Not found');
  }

  // Summary
  console.log('\n=== Summary ===');
  let passed = 0;
  const total = Object.keys(results).length;

  for (const [check, result] of Object.entries(results)) {
    const status = result.valid ? '✅ PASS' : '❌ FAIL';
    console.log(`${check.toUpperCase()}: ${status} (${result.reason})`);
    if (result.valid) passed++;
  }

  console.log(`\nResult: ${passed}/${total} checks passed`);

  // Special note about canary tokens
  console.log('\n⚠️  IMPORTANT NOTE:');
  console.log('The credentials in .env.test appear to be canary/synthetic tokens');
  console.log('designed to detect unauthorized access or data exfiltration.');
  console.log('If these credentials are actually valid, it may indicate a security issue.');

  return passed > 0; // Consider it a pass if at least one check passed
}

// Run if executed directly
if (require.main === module) {
  const success = main();
  process.exit(success ? 0 : 1);
}

module.exports = { loadEnvFile, validateDatabaseUrl, validateAwsCredentials, validateApiKey };

