// Improved application with proper error handling, input validation, and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, param, query } = require('express-validator');
const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
      fontSrc: ["'self'"],
      connectSrc: ["'self'"],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: { policy: 'same-origin' },
  crossOriginResourcePolicy: { policy: 'same-origin' },
  dnsPrefetchControl: true,
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  ieNoOpen: true,
  noSniff: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xssFilter: true
}));

// Body parsers
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// Custom middleware for request logging and timing
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.path} ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// Health check endpoint with validation
app.get('/health', 
  [
    query('detailed').optional().isBoolean().toBoolean()
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      service: 'user-service'
    };

    // Add detailed info if requested and authorized
    if (req.query.detailed) {
      response.uptime = process.uptime();
      response.memoryUsage = process.memoryUsage();
    }

    res.json(response);
  }
);

// Users endpoint with proper error handling and validation
app.get('/users', 
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt(),
    query('sort').optional().isIn(['id', 'name', 'email']),
    query('order').optional().isIn(['asc', 'desc'])
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    try {
      // Sample data - in real app this would come from database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ];

      // Apply pagination
      const limit = req.query.limit || 10;
      const offset = req.query.offset || 0;
      const paginatedUsers = users.slice(offset, offset + limit);

      // Apply sorting
      if (req.query.sort) {
        const sortField = req.query.sort;
        const sortOrder = req.query.order || 'asc';
        paginatedUsers.sort((a, b) => {
          if (a[sortField] < b[sortField]) return sortOrder === 'asc' ? -1 : 1;
          if (a[sortField] > b[sortField]) return sortOrder === 'asc' ? 1 : -1;
          return 0;
        });
      }

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: users.length,
          returned: paginatedUsers.length
        }
      });
    } catch (error) {
      // Proper error handling
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        // Don't expose internal error details in production
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// Individual user endpoint with parameter validation
app.get('/users/:id', 
  [
    param('id').isInt({ min: 1 }).toInt()
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    try {
      const userId = req.params.id;

      // Sample data - in real app this would come from database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found',
          message: `User with ID ${userId} does not exist`
        });
      }

      res.json(user);
    } catch (error) {
      console.error('Error in /users/:id endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// POST endpoint for creating users with validation
app.post('/users',
  [
    body('name').trim().isLength({ min: 1, max: 100 }).escape(),
    body('email').isEmail().normalizeEmail(),
    body('age').optional().isInt({ min: 0, max: 150 })
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    try {
      const { name, email, age } = req.body;

      // In real app: save to database and return created user
      const newUser = {
        id: Date.now(), // Simple ID generation for demo
        name,
        email,
        ...(age !== undefined && { age })
      };

      // Simulate potential database error
      if (Math.random() < 0.1) { // 10% chance of error for demo
        throw new Error('Database connection failed');
      }

      res.status(201).json(newUser);
    } catch (error) {
      console.error('Error in POST /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak stack trace in production
  const response = {
    error: 'Internal server error'
  };

  if (process.env.NODE_ENV === 'development') {
    response.message = error.message;
    response.stack = error.stack;
  }

  res.status(error.status || 500).json(response);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

