      const response = await request(app).get('/users?limit=0');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should validate offset parameter', async () => {
      const response = await request(app).get('/users?offset=-1');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should validate sort parameter', async () => {
      const response = await request(app).get('/users?sort=invalid');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should validate order parameter', async () => {
      const response = await request(app).get('/users?order=invalid');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });
  });

  describe('Individual User Endpoint', () => {
    test('should return user by valid ID', async () => {
      const response = await request(app).get('/users/1');
      expect(response.status).toBe(200);
      expect(response.body.id).toBe(1);
      expect(response.body.name).toBe('Alice');
    });

    test('should reject non-numeric ID', async () => {
      const response = await request(app).get('/users/abc');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should reject negative ID', async () => {
      const response = await request(app).get('/users/-1');
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('should return 404 for non-existent user', async () => {
      const response = await request(app).get('/users/999');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('User not found');
    });
  });

  describe('POST Users Endpoint', () => {
    test('should create user with valid data', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'John Doe', email: 'john@example.com', age: 30 })
        .expect(201);

      expect(response.body.name).toBe('John Doe');
      expect(response.body.email).toBe('john@example.com');
      expect(response.body.age).toBe(30);
    });

    test('should reject invalid name', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: '', email: 'test@example.com' })
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should reject invalid email', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'Test User', email: 'invalid-email' })
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should sanitize input data', async () => {
      const response = await request(app)
        .post('/users')
        .send({ 
          name: '<script>alert("xss")</script>John', 
          email: 'john@example.com' 
        })
        .expect(201);

      // Should be sanitized/escaped
      expect(response.body.name).toContain('John');
      expect(response.body.name).not.toContain('<script>');
    });

    test('should reject age out of range', async () => {
      const response = await request(app)
        .post('/users')
        .send({ name: 'Test User', email: 'test@example.com', age: 200 })
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });
  });

  describe('Security Headers', () => {
    test('should set security headers', async () => {
      const response = await request(app).get('/health');
      expect(response.headers).toHaveProperty('x-content-type-options');
      expect(response.headers).toHaveProperty('x-frame-options');
      expect(response.headers).toHaveProperty('strict-transport-security');
      expect(response.headers).toHaveProperty('referrer-policy');
      expect(response.headers).toHaveProperty('x-xss-protection');
    });
  });

  describe('Rate Limiting', () => {
    test('should apply rate limiting', async () => {
      // Make multiple requests quickly
      const promises = [];
      for (let i = 0; i < 5; i++) {
        promises.push(request(app).get('/health'));
      }

      const responses = await Promise.all(promises);
      // All should succeed since we're under the limit
      responses.forEach(response => {
        expect(response.status).toBe(200);
      });
    });
  });

  describe('Error Handling', () => {
    test('should handle 404 for undefined routes', async () => {
      const response = await request(app).get('/undefined-route');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not found');
    });

    test('should not leak stack trace in production-like mode', async () => {
      // Temporarily set NODE_ENV to production
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      try {
        const response = await request(app).get('/users/999);
        // Even if there's an error, it shouldn't expose stack trace
        expect(response.body.stack).toBeUndefined();
      } finally {
        process.env.NODE_ENV = originalEnv;
      }
    });
  });
});

