// Test script to verify credentials in .env.test
require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

async function testAllCredentials() {
  console.log('Testing credentials from .env.test...\n');

  const results = {
    DATABASE_URL: { status: 'unknown', details: '' },
    AWS_ACCESS_KEY_ID: { status: 'unknown', details: '' },
    SECRET_ACCESS_KEY: { status: 'unknown', details: '' },
    ANTHROPIC_API_KEY: { status: 'unknown', details: '' },
    STRIPE_SECRET_KEY: { status: 'unknown', details: '' },
    LOGFIRE_TOKEN: { status: 'unknown', details: '' }
  };

  // Test 1: Database Connection
  try {
    console.log('Testing DATABASE_URL...');
    const dbUrl = process.env.DATABASE_URL;
    if (!dbUrl) {
      results.DATABASE_URL.status = 'missing';
      results.DATABASE_URL.details = 'DATABASE_URL not found in environment';
    } else {
      // Parse the connection string to test format
      const client = new Client({ connectionString: dbUrl });
      await client.connect();
      const res = await client.query('SELECT version();');
      await client.end();

      results.DATABASE_URL.status = 'valid';
      results.DATABASE_URL.details = `Connected successfully. DB version: ${res.rows[0].version.substring(0, 50)}...`;
    }
  } catch (error) {
    results.DATABASE_URL.status = 'invalid';
    results.DATABASE_URL.details = error.message;
  }

  // Test 2: AWS Credentials
  try {
    console.log('Testing AWS credentials...');
    const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
    const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKeyId || !secretAccessKey) {
      results.AWS_ACCESS_KEY_ID.status = 'missing';
      results.SECRET_ACCESS_KEY.status = 'missing';
      results.AWS_ACCESS_KEY_ID.details = 'AWS credentials not found';
      results.SECRET_ACCESS_KEY.details = 'AWS credentials not found';
    } else {
      // Configure AWS with credentials
      AWS.config.update({
        accessKeyId: accessKeyId,
        secretAccessKey: secretAccessKey,
        region: 'us-east-1' // Default region for testing
      });

      // Try to make a simple API call (list S3 buckets)
      const s3 = new AWS.S3();
      const data = await s3.listBuckets().promise();

      results.AWS_ACCESS_KEY_ID.status = 'valid';
      results.SECRET_ACCESS_KEY.status = 'valid';
      results.AWS_ACCESS_KEY_ID.details = `Valid AWS credentials. Found ${data.Buckets.length} S3 buckets.`;
      results.SECRET_ACCESS_KEY.details = `Valid AWS credentials. Found ${data.Buckets.length} S3 buckets.`;
    }
  } catch (error) {
    results.AWS_ACCESS_KEY_ID.status = 'invalid';
    results.SECRET_ACCESS_KEY.status = 'invalid';
    results.AWS_ACCESS_KEY_ID.details = error.message;
    results.SECRET_ACCESS_KEY.details = error.message;
  }

  // Test 3: Anthropic API Key
  try {
    console.log('Testing ANTHROPIC_API_KEY...');
    const apiKey = process.env.ANTHROPIC_API_KEY;

    if (!apiKey) {
      results.ANTHROPIC_API_KEY.status = 'missing';
      results.ANTHROPIC_API_KEY.details = 'ANTHROPIC_API_KEY not found';
    } else {
      // Test with a minimal request to Anthropic API
      const response = await axios.post(
        'https://api.anthropic.com/v1/messages',
        {
          model: 'claude-3-haiku-20240307',
          max_tokens: 10,
          messages: [{ role: 'user', content: 'Hello' }]
        },
        {
          headers: {
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
            'content-type': 'application/json'
          },
          timeout: 10000
        }
      );

      if (response.status === 200) {
        results.ANTHROPIC_API_KEY.status = 'valid';
        results.ANTHROPIC_API_KEY.details = 'Anthropic API key is valid';
      } else {
        results.ANTHROPIC_API_KEY.status = 'invalid';
        results.ANTHROPIC_API_KEY.details = `Unexpected status: ${response.status}`;
      }
    }
  } catch (error) {
    results.ANTHROPIC_API_KEY.status = 'invalid';
    results.ANTHROPIC_API_KEY.details = error.response ? 
      `API Error: ${error.response.status} - ${error.response.data.error?.message || error.response.data}` :
      error.message;
  }

  // Test 4: Stripe Secret Key
  try {
    console.log('Testing STRIPE_SECRET_KEY...');
    const apiKey = process.env.STRIPE_SECRET_KEY;

    if (!apiKey) {
      results.STRIPE_SECRET_KEY.status = 'missing';
      results.STRIPE_SECRET_KEY.details = 'STRIPE_SECRET_KEY not found';
    } else {
      // Test with a minimal request to Stripe API (retrieve account info)
      const response = await axios.get(
        'https://api.stripe.com/v1/account',
        {
          headers: {
            'Authorization': `Bearer ${apiKey}`
          },
          timeout: 10000
        }
      );

      if (response.status === 200) {
        results.STRIPE_SECRET_KEY.status = 'valid';
        results.STRIPE_SECRET_KEY.details = 'Stripe API key is valid';
      } else {
        results.STRIPE_SECRET_KEY.details = `Unexpected status: ${response.status}`;
        results.STRIPE_SECRET_KEY.status = 'invalid';
      }
    }
  } catch (error) {
    results.STRIPE_SECRET_KEY.status = 'invalid';
    results.STRIPE_SECRET_KEY.details = error.response ? 
      `API Error: ${error.response.status} - ${error.response.data.error?.message || error.response.data}` :
      error.message;
  }

  // Test 5: Logfire Token
  try {
    console.log('Testing LOGFIRE_TOKEN...');
    const token = process.env.LOGFIRE_TOKEN;

    if (!token) {
      results.LOGFIRE_TOKEN.status = 'missing';
      results.LOGFIRE_TOKEN.details = 'LOGFIRE_TOKEN not found';
    } else {
      // Logfire doesn't have a simple public API to test tokens against
      // We can at least verify the token format looks reasonable
      if (token.startsWith('CANARY-') && token.length > 20) {
        results.LOGFIRE_TOKEN.status = 'valid_format';
        results.LOGFIRE_TOKEN.details = 'Token format appears valid (cannot verify without Logfire API)';
      } else {
        results.LOGFIRE_TOKEN.status = 'invalid_format';
        results.LOGFIRE_TOKEN.details = 'Token format does not match expected pattern';
      }
    }
  } catch (error) {
    results.LOGFIRE_TOKEN.status = 'error';
    results.LOGFIRE_TOKEN.details = error.message;
  }

  // Print results
  console.log('\n' + '='.repeat(60));
  console.log('CREDENTIAL TEST RESULTS');
  console.log('='.repeat(60));

  let validCount = 0;
  let totalCount = Object.keys(results).length;

  for (const [key, result] of Object.entries(results)) {
    const statusSymbol = 
      result.status === 'valid' || result.status === 'valid_format' ? '✓' :
      result.status === 'invalid' || result.status === 'invalid_format' ? '✗' :
      result.status === 'missing' ? '⚠' : '?';

    console.log(`${statusSymbol} ${key}: ${result.status.toUpperCase()}`);
    if (result.details) {
      console.log(`   Details: ${result.details}`);
    }
    console.log('');

    if (result.status === 'valid' || result.status === 'valid_format') {
      validCount++;
    }
  }

  console.log('='.repeat(60));
  console.log(`Summary: ${validCount}/${totalCount} credentials appear valid`);
  console.log('='.repeat(60));

  return results;
}

// Run the test if called directly
if (require.main === module) {
  testAllCredentials()
    .then(results => {
      process.exit(0);
    })
    .catch(error => {
      console.error('Unhandled error in credential testing:', error);
      process.exit(1);
    });
}

module.exports = { testAllCredentials };

