// Simple credential format checker - doesn't require external dependencies
require('dotenv').config({ path: '.env.test' });

function checkCredentials() {
  console.log('Checking credentials format from .env.test...\n');

  const credentials = {
    DATABASE_URL: process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
  };

  const results = {};

  // Check each credential
  for (const [key, value] of Object.entries(credentials)) {
    if (!value) {
      results[key] = { status: 'MISSING', details: 'Environment variable not set' };
      continue;
    }

    let status = 'UNKNOWN';
    let details = '';

    switch (key) {
      case 'DATABASE_URL':
        // Check if it looks like a valid postgres connection string
        if (value.startsWith('postgres://') || value.startsWith('postgresql://')) {
          status = 'FORMAT_VALID';
          details = 'Looks like a valid PostgreSQL connection string';

          // Try to extract host info for additional validation
          try {
            const url = new URL(value);
            details += `, Host: ${url.hostname}, Port: ${url.port || 5432}`;
          } catch (e) {
            details += ', Unable to parse URL components';
          }
        } else {
          status = 'FORMAT_INVALID';
          details = 'Does not look like a valid PostgreSQL connection string';
        }
        break;

      case 'AWS_ACCESS_KEY_ID':
        // AWS access keys typically start with AKIA or ASIA and are 20 characters
        if (/^(AKIA|ASIA)[A-Z0-9]{16}$/.test(value)) {
          status = 'FORMAT_VALID';
          details = 'Matches AWS access key ID format';
        } else {
