      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
    return {};
  }
}

function checkForCanaryValues(value) {
  // Common patterns that indicate test/canary values
  const canaryPatterns = [
    /CANARY[-_]/i,
    /test[-_]/i,
    /fake[-_]/i,
    /example[-_]/i,
    /dummy[-_]/i,
    /1234567890/, // Obvious test sequences
    /abcdefghij/,  // Obvious test sequences
    /CHANGE_ME/i,
    /YOUR_.*_HERE/i
  ];

  return canaryPatterns.some(pattern => pattern.test(value));
}

function checkCredentials() {
  console.log('Checking credentials for canary/test values and format validity...\n');

  // Load environment variables from .env.test
  const envVars = parseEnvFile('.env.test');

  const credentials = {
    DATABASE_URL: envVars.DATABASE_URL,
    AWS_ACCESS_KEY_ID: envVars.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: envVars.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: envVars.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: envVars.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: envVars.LOGFIRE_TOKEN
  };

  const results = {};

  // Check each credential
  for (const [key, value] of Object.entries(credentials)) {
    if (!value) {
      results[key] = { status: 'MISSING', details: 'Environment variable not set in .env.test', isCanary: false };
      continue;
    }

    // First check if it's a canary value
    const isCanary = checkForCanaryValues(value);

    if (isCanary) {
      results[key] = { 
        status: 'CANARY_DETECTED', 
        details: 'This appears to be a test/canary value, not a real credential',
        isCanary: true
      };
      continue;
    }

    // If not a canary, check format validity
    let status = 'UNKNOWN';
    let details = '';

    switch (key) {
      case 'DATABASE_URL':
        // Check if it looks like a valid postgres connection string
        if (value.startsWith('postgres://') || value.startsWith('postgresql://')) {
          status = 'FORMAT_VALID';
          details = 'Looks like a valid PostgreSQL connection string';

          // Try to extract host info for additional validation
          try {
