            const urlMatch = value.match(/^(?:postgres|postgresql):\/\/([^:@]+)(?::([^@]*))?@([^:/]+)(?::(\d+))?\/(.*)$/);
            if (urlMatch) {
              const [, username, password, host, port, database] = urlMatch;
