      case 'AWS_SECRET_ACCESS_KEY':
        // AWS secret keys are 40 characters of base64-like characters
        if (/^[A-Za-z0-9\/+]{40}$/.test(value)) {
          status = 'FORMAT_VALID';
          details = 'Matches AWS secret access key format';
        } else {
          status = 'FORMAT_INVALID';
          details = 'Does not match AWS secret access key format (should be 40 base64 chars)';
        }
        break;

      case 'ANTHROPIC_API_KEY':
        // Anthropic API keys start with sk-ant-
        if (value.startsWith('sk-ant-') && value.length > 20) {
          status = 'FORMAT_VALID';
          details = 'Matches Anthropic API key format';
        } else {
          status = 'FORMAT_INVALID';
          details = 'Does not match Anthropic API key format (should start with sk-ant-)';
        }
        break;

      case 'STRIPE_SECRET_KEY':
        // Stripe secret keys start with sk_live_ or sk_test_
        if (value.startsWith('sk_live_') || value.startsWith('sk_test_')) {
          status = 'FORMAT_VALID';
          details = 'Matches Stripe secret key format';
        } else {
          status = 'FORMAT_INVALID';
          details = 'Does not match Stripe secret key format (should start with sk_live_ or sk_test_)';
        }
        break;

      case 'LOGFIRE_TOKEN':
        // Logfire tokens - we don't have a specific format to check against
        // but we know it's marked as CANARY in the comments
        if (value.length > 10) {
          status = 'LIKELY_FORMAT_VALID';
          details = 'Appears to be a reasonable token length';
        } else {
          status = 'FORMAT_INVALID';
          details = 'Token too short to be valid';
        }
        break;

