// Improved application with proper error handling, input validation, and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Sanitize against NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    if (Object.keys(req.query).length > 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Health endpoint does not accept query parameters'
      });
    }

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to process health check'
    });
  }
});

// Users endpoint with proper validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Validate limit parameter
    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Limit must be a number between 1 and 100'
        });
      }
    }

    // Validate offset parameter
    if (offset !== undefined) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Offset must be a non-negative number'
        });
      }
    }

    // Sample data - in real app this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search !== undefined) {
      // Sanitize search input (basic example - in practice use proper validation)
      const sanitizedSearch = search.toString().substring(0, 50); // Limit length
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
        user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
      );
    }

    // Apply pagination
    const limitNum = limit !== undefined ? parseInt(limit, 10) : 10;
    const offsetNum = offset !== undefined ? parseInt(offset, 10) : 0;

    const paginatedUsers = filteredUsers.slice(offsetNum, offsetNum + limitNum);

    res.json({
      count: filteredUsers.length,
      limit: limitNum,
      offset: offsetNum,
      data: paginatedUsers
    });
  } catch (error) {
    // Log the error for debugging (in production, use proper logger)
    console.error('Error in /users endpoint:', error);

    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging
  console.error('Unhandled error:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // Don't leak stack trace in production
  const response = {
    error: statusCode === 500 ? 'Internal Server Error' : 'Bad Request',
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong' 
      : err.message
  };

  // Only include stack trace in development
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

module.exports = app;

