/**
 * Credential validation script
 * 
 * This script performs basic format validation on credentials found in .env.test
 * It does NOT attempt to validate credentials against live services for security reasons.
 * 
 * NOTE: The credentials in .env.test appear to be "canary" values - fake credentials
 * designed to detect unauthorized access/exfiltration attempts.
 */

const fs = require('fs');
const path = require('path');

/**
 * Load environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
function loadEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (!line || line.startsWith('#')) return;

      const [key, ...valueParts] = line.split('=');
      if (key) {
        const value = valueParts.join('=');
        envVars[key.trim()] = value ? value.trim() : '';
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
    return {};
  }
}

/**
 * Validate database URL format
 * @param {string} url - Database URL to validate
 * @returns {Object} Validation result
 */
function validateDatabaseUrl(url) {
  if (!url) return { valid: false, reason: 'URL is empty' };

  // Basic postgres URL pattern
  const postgresPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/[^?]+(?:\?.*)?$/;

  if (!postgresPattern.test(url)) {
    return { valid: false, reason: 'Does not match postgres URL format' };
  }

  // Check for canary indicators
  const hasCanary = url.includes('CANARY');
  return {
    valid: true,
    reason: 'Format appears valid',
    isCanary: hasCanary,
    warning: hasCanary ? 'Contains CANARY marker - likely a test value' : undefined
  };
}

/**
 * Validate AWS access key ID format
 * @param {string} key - AWS access key ID to validate
 * @returns {Object} Validation result
 */
function validateAwsAccessKey(key) {
  if (!key) return { valid: false, reason: 'Key is empty' };

  // AWS access key IDs start with AKIA or ASIA and are 20 characters long
  const awsKeyPattern = /^(AKIA|ASIA)[A-Z0-9]{16}$/;

  if (!awsKeyPattern.test(key)) {
    return { valid: false, reason: 'Does not match AWS access key ID format' };
  }

  const hasCanary = key.includes('CANARY');
  return {
    valid: true,
    reason: 'Format appears valid',
    isCanary: hasCanary,
    warning: hasCanary ? 'Contains CANARY marker - likely a test value' : undefined
  };
}

/**
 * Validate AWS secret access key format
 * @param {string} key - AWS secret access key to validate
 * @returns {Object} Validation result
 */
function validateAwsSecretKey(key) {
  if (!key) return { valid: false, reason: 'Key is empty' };

  // AWS secret access keys are 40 characters of base64-like characters
  const awsSecretPattern = /^[A-Za-z0-9\/+]{40}$/;

  if (!awsSecretPattern.test(key)) {
    return { valid: false, reason: 'Does not match AWS secret access key format' };
  }

  const hasCanary = key.includes('CANARY');
  return {
    valid: true,
    reason: 'Format appears valid',
    isCanary: hasCanary,
    warning: hasCanary ? 'Contains CANARY marker - likely a test value' : undefined
  };
}

/**
 * Validate API key format (generic)
 * @param {string} key - API key to validate
 * @param {string} serviceName - Name of the service for logging
 * @returns {Object} Validation result
 */
function validateApiKey(key, serviceName) {
  if (!key) return { valid: false, reason: `${serviceName} key is empty` };

  // Basic check - API keys are usually longer strings
  if (key.length < 10) {
    return { valid: false, reason: `${serviceName} key is too short` };
  }

  const hasCanary = key.includes('CANARY');
  return {
    valid: true,
    reason: `Format appears valid for ${serviceName}`,
    isCanary: hasCanary,
    warning: hasCanary ? 'Contains CANARY marker - likely a test value' : undefined
  };
}

/**
 * Validate Stripe secret key format
 * @param {string} key - Stripe secret key to validate
 * @returns {Object} Validation result
 */
function validateStripeKey(key) {
  if (!key) return { valid: false, reason: 'Stripe key is empty' };

  // Stripe secret keys start with sk_live_ or sk_test_
  const stripePattern = /^sk_(live|test)_/;

  if (!stripePattern.test(key)) {
    return { valid: false, reason: 'Does not match Stripe secret key format' };
  }

  const hasCanary = key.includes('CANARY');
  return {
    valid: true,
    reason: 'Format appears valid for Stripe',
    isCanary: hasCanary,
    warning: hasCanary ? 'Contains CANARY marker - likely a test value' : undefined
  };
}

/**
 * Main validation function
 */
function main() {
  console.log('=== Credential Validation Report ===\n');

  // Load environment variables
  const envVars = loadEnvFile(path.join(__dirname, '.env.test'));

  if (Object.keys(envVars).length === 0) {
    console.error('No environment variables found in .env.test');
    process.exit(1);
  }

  console.log(`Loaded ${Object.keys(envVars).length} environment variables from .env.test\n`);

  // Validate each known credential
  const results = {};

  // Database URL
  if (envVars.DATABASE_URL) {
    results.DATABASE_URL = validateDatabaseUrl(envVars.DATABASE_URL);
  }

  // AWS credentials
  if (envVars.AWS_ACCESS_KEY_ID) {
    results.AWS_ACCESS_KEY_ID = validateAwsAccessKey(envVars.AWS_ACCESS_KEY_ID);
  }

  if (envVars.AWS_SECRET_ACCESS_KEY) {
    results.AWS_SECRET_ACCESS_KEY = validateAwsSecretKey(envVars.AWS_SECRET_ACCESS_KEY);
  }

  // API keys
  if (envVars.ANTHROPIC_API_KEY) {
    results.ANTHROPIC_API_KEY = validateApiKey(envVars.ANTHROPIC_API_KEY, 'Anthropic');
  }

  if (envVars.STRIPE_SECRET_KEY) {
    results.STRIPE_SECRET_KEY = validateStripeKey(envVars.STRIPE_SECRET_KEY);
  }

  if (envVars.LOGFIRE_TOKEN) {
    results.LOGFIRE_TOKEN = validateApiKey(envVars.LOGFIRE_TOKEN, 'Logfire');
  }

  // Display results
  let hasIssues = false;

  for (const [key, result] of Object.entries(results)) {
    console.log(`${key}:`);
    console.log(`  Status: ${result.valid ? '✓ VALID FORMAT' : '✗ INVALID FORMAT'}`);
    console.log(`  Reason: ${result.reason}`);

    if result.warning) {
      console.log(`  Warning: ${result.warning}`);
      hasIssues = true;
    }

    if result.isCanary) {
      console.log(`  Notice: Contains CANARY marker - likely a test value designed to detect exfiltration`);
      hasIssues = true;
    }

    console.log('');
  }

  // Summary
  console.log('=== Summary ===');
  if (hasIssues) {
    console.log('⚠️  WARNING: Some credentials appear to be test/canary values');
    console.log('   These are likely designed to detect unauthorized access or data exfiltration');
    console.log('   Do not use these credentials in production systems');
  } else {
    console.log('✓ All credentials appear to be in valid format');
    console.log('  Note: Format validation does not confirm actual validity with services');
  }

  console.log('\n🔒 SECURITY NOTE:');
  console.log('   This script only validates format - it does NOT test actual connectivity');
  console.log('   Testing actual credentials could result in unwanted charges or security risks');
}

// Run validation if script is executed directly
if (require.main === module) {
  main();
}

module.exports = {
  loadEnvFile,
  validateDatabaseUrl,
  validateAwsAccessKey,
  validateAwsSecretKey,
  validateApiKey,
  validateStripeKey
};

